// Ісуса Навина — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Після смерти Мойсея, раба Господнього, Господь сказав Ісусові, синові Навина, служителеві Мойсея:","Мойсей, раб Мій, помер; отже, встань, перейди через Йордан цей, ти і весь народ цей, у землю, яку Я даю їм, синам Ізраїлевим.","Усяке місце, на яке ступлять стопи ніг ваших, Я даю вам, як Я сказав Мойсеєві:","від пустелі й Ливану цього до ріки великої, ріки Євфрату, всю землю хеттеїв; і до великого моря до заходу сонця будуть кордони ваші.","Ніхто не устоїть перед тобою в усі дні життя твого; і як Я був з Мойсеєм, так буду і з тобою: не відступлю від тебе і не залишу тебе.","Будь твердим і мужнім; тому що ти народу цьому передаси у володіння землю, яку Я клявся батькам їхнім дати їм;","тільки будь твердим і дуже мужнім, і старанно зберігай і виконуй весь закон, який заповідав тобі Мойсей, раб Мій; не ухиляйся від нього ні праворуч, ні ліворуч, щоб чинити розсудливо в усіх починаннях твоїх.","Нехай не відходить ця книга закону від вуст твоїх; але повчайся в ній день і ніч, щоб ретельно виконувати усе, що в ній написано: тоді ти будеш мати успіх в путях твоїх і будеш чинити розсудливо.","Ось Я повеліваю тобі: будь твердим і мужнім, не страшися і не жахайся; бо з тобою Господь Бог твій скрізь, куди підеш.","І дав Ісус повеління наглядачам народу і сказав:","пройдіть по стану і дайте повеління народу і скажіть: заготовляйте собі їжу на дорогу, тому що через три дні ви підете за Йордан цей, щоб прийти взяти землю, яку Господь Бог [батьків] ваших дає нам у спадщину.","А коліну Рувимовому, Гадовому і половині коліна Манассіїного Ісус сказав:","згадайте, що заповів вам Мойсей, раб Господній, говорячи: Господь Бог ваш заспокоїв вас і дав вам землю цю;","дружини ваші, діти ваші і худоба ваша нехай залишаться в землі, яку дав вам Мойсей за Йорданом; а ви всі, здатні воювати, озброївшись, ідіть перед братами вашими і допомагайте їм,","доки Господь [Бог ваш] не заспокоїть братів ваших, як і вас; доки і вони не одержать у спадщину землю, яку Господь Бог ваш дає їм; тоді повернетеся у спадщину вашу і володійте землею, яку Мойсей, раб Господній, дав вам за Йорданом на схід сонця.","Вони у відповідь Ісусові сказали: усе, що звелиш нам, зробимо, і куди пошлеш нас, підемо;","як слухали ми Мойсея, так будемо слухати і тебе: тільки Господь, Бог твій, нехай буде з тобою, як Він був з Мойсеєм;","всякий, хто стане проти веління твого і не послухає слів твоїх в усьому, що ти звелиш йому, буде відданий на смерть. Тільки будь твердим і мужнім!"],"x":{"1":"1.17.9|3.27.18","2":"4.34.5","3":"4.11.24|5.14.9","4":"1.23.31","5":"75.13.5","6":"4.1.38|4.3.28|4.31.7","7":"75.3.5","8":"25.1.2","11":"5.3.2","13":"3.32.20","14":"3.32.29|5.4.12","16":"1.19.8"}},{"v":["І послав Ісус, син Навина, з Ситтима двох спостерігачів таємно і сказав: підіть, огляньте землю і Єрихон. [Два юнаки] пішли і прийшли [у Єрихон і ввійшли] у дім блудниці, ім’я якої Раав, і залишилися ночувати там.","І сказано було цареві Єрихонському: ось, якісь люди із синів Ізраїлевих прийшли сюди в цю ніч, щоб видивитися землю.","Цар Єрихонський послав сказати Рааві: видай людей, які прийшли до тебе, які ввійшли у твій дім [вночі], тому що вони прийшли видивитись усю землю.","Але жінка взяла двох людей тих і сховала їх і сказала: дійсно, приходили до мене люди, але я не знала, звідки вони;","коли ж у сутінках належало зачиняти ворота, тоді вони пішли; не знаю, куди вони пішли; гоніться швидше за ними, ви наздоженете їх.","А сама відвела їх на покрівлю і сховала їх у снопах льону, розкладених у неї на покрівлі.","Послані гналися за ними по дорозі до Йордану до самої переправи; ворота ж негайно зачинили, після того як вийшли ті, що гналися за ними.","Перш ніж вони лягли спати, вона піднялася до них на покрівлю","і сказала їм: я знаю, що Господь віддав землю цю вам, тому що ви навели на нас жах, і всі жителі землі цієї прийшли від вас у страх;","бо ми чули, як Господь [Бог] висушив перед вами воду Червоного моря, коли ви йшли з Єгипту, і як ви вчинили з двома царями аморрейськими за Йорданом, з Сигоном і Огом, яких ви знищили;","коли ми почули про це, ослабло серце наше, і ні в кому [з нас] не стало духу проти вас; бо Господь Бог ваш є Бог на небі вгорі і на землі внизу;","отже, покляніться мені Господом [Богом вашим], що, як я зробила вам милість, так і ви зробите милість дому батька мого, і дайте мені вірний знак,","що ви залишите в живих батька мого і матір мою, і братів моїх, і сестер моїх, і всіх, хто є в них, і визволите душі наші від смерти.","Ці люди сказали їй: душа наша замість вас нехай буде віддана на смерть, якщо ви [нині] не відкриєте цієї справи нашої; коли ж Господь віддасть нам землю, ми зробимо тобі милість і істину.","І спустила вона їх на мотузці через вікно, бо дім її був у міській стіні, і вона жила в стіні;","і сказала їм: ідіть на гору, щоб не зустріли вас ті, що переслідують, і ховайтеся там три дні, доки не повернуться ті, що погналися [за вами]; а потім підете в дорогу вашу.","І сказали їй ті люди: ми вільні будемо від твоєї клятви, якою ти нас закляла, якщо не зробиш так:","ось, коли ми прийдемо в цю землю, ти прив’яжи червлену мотузку до вікна, через яке ти нас спустила, а батька твого і матір твою, і братів твоїх, усю родину батька твого збери до себе в дім твій;","і якщо хто-небудь вийде з дверей твого дому геть, того кров на голові його, а ми вільні [будемо від цієї клятви твоєї]; а хто буде з тобою в [твоєму] домі, того кров на голові нашій, якщо чия рука торкнеться його;","якщо ж [хто нас скривдить, або] ти відкриєш цю нашу справу, то ми також вільні будемо від клятви твоєї, якою ти нас закляла.","Вона сказала: нехай буде за словами вашими! І відпустила їх, і вони пішли, а вона прив’язала до вікна червлену мотузку.","Вони пішли і піднялися на гору, і пробули там три дні, доки не повернулися ті, що гналися за ними. Ті, що гналися, шукали їх по всій дорозі і не знайшли.","Таким чином двоє цих людей пішли назад, зійшли з гори, перейшли [Йордан] і прийшли до Ісуса, сина Навина, і переказали йому все, що з ними трапилося.","І сказали Ісусові: Господь [Бог наш] віддав усю землю цю в руки наші, і всі жителі землі в страху від нас."],"x":{"1":"5.7.2|3.25.1|55.2.25|75.11.31","4":"5.6.16","9":"3.21.3","10":"1.14.21|3.21.23-24","11":"1.15.14|4.4.39","12":"5.6.16:22"}},{"v":["І встав Ісус рано-вранці, і рушили вони від Ситтима і прийшли до Йордану, він і всі сини Ізраїлеві, і ночували там, ще не переходячи його.","Через три дні пішли наглядачі по стану","і дали народу повеління, говорячи: коли побачите ковчег завіту Господа Бога вашого і священиків [наших і] левитів, які несуть його, то і ви руште з місця свого і йдіть за ним;","утім, відстань між вами і ним повинна бути до двох тисяч ліктів мірою; не підходьте до нього близько, щоб знати вам дорогу, по якій іти; бо ви не ходили цією дорогою ні вчора, ні третього дня.","І сказав Ісус народу: освятіться [до ранку], бо завтра створить Господь серед вас чудеса.","Священикам же сказав Ісус: візьміть ковчег завіту [Господнього] і йдіть перед народом. [Священики] взяли ковчег завіту [Господнього] і пішли перед народом.","Тоді Господь сказав Ісусові: у цей день Я почну прославляти тебе перед очима всіх [синів] Ізраїля, щоб вони зрозуміли, що як Я був з Мойсеєм, так буду і з тобою;","а ти дай повеління священикам, які несуть ковчег завіту, і скажи: як тільки ввійдете у води Йордану, зупиніться в Йордані.","Ісус сказав синам Ізраїлевим: підійдіть сюди і вислухайте слова Господа, Бога вашого.","І сказав Ісус: з цього довідаєтеся, що серед вас є Бог живий, Який прожене від вас хананеїв і хеттеїв, і евеїв, і ферезеїв, і гергесеїв, і аморреїв, і ієвусеїв:","ось, ковчег завіту Господа всієї землі піде перед вами через Йордан;","і візьміть собі дванадцять чоловік з колін Ізраїлевих, по одній людині з коліна;","і як тільки стопи ніг священиків, які несуть ковчег Господа, Владики всієї землі, ступлять у воду Йордану, вода Йорданська висохне, та ж вода, що тече згори, зупиниться стіною.","Отже, коли народ рушив від своїх наметів, щоб переходити Йордан, і священики понесли ковчег завіту [Господнього] перед народом,","то, лиш тільки ті, що несли ковчег [завіту Господнього], ввійшли в Йордан, і ноги священиків, які несли ковчег, занурилися у воду Йордану — Йордан же виступає з усіх берегів своїх в усі дні жнив пшениці, —","вода, що текла згори, зупинилася і стала стіною на дуже велику відстань, до міста Адама, що поряд Цартана; а та, що тече в море рівнини, у море Солоне, пішла і припинилася.","І народ переходив навпроти Єрихона; священики ж, які несли ковчег завіту Господнього, стояли на суші посеред Йордану твердою ногою. Всі [сини] Ізраїлеві переходили по суші, доки весь народ не перейшов через Йордан."],"x":{"1":"5.6.12|3.25.1","5":"1.19.10|2.20.7","6":"3.4.15","7":"5.4.14","10":"32.10.10|0.15.19|1.3.8","11":"54.7.45|25.8.2","13":"25.113.3","14":"54.7.45","15":"12.12.15|30.24.28","16":"1.14.21|45.3.9"}},{"v":["Коли весь народ перейшов через Йордан, Господь сказав Ісусові:","візьміть собі з народу дванадцять чоловік, по одній людині з коліна,","і дайте їм повеління і скажіть: візьміть собі звідси, із середини Йордану, де стояли ноги священиків нерухомо, дванадцять каменів, і перенесіть їх із собою, і покладіть їх на ночівлі, де будете ночувати в цю ніч.","Ісус покликав дванадцять чоловіків, яких призначив із синів Ізраїлевих, по одній людині з коліна,","і сказав їм Ісус: підіть перед ковчегом Господа Бога вашого на середину Йордану і [візьміть звідти і] покладіть на плече своє кожен по одному каменю, за числом колін синів Ізраїлевих,","щоб вони були у вас знаменням [що лежить завжди]; коли запитають вас у наступний час сини ваші і скажуть: «для чого у вас ці камені?»,","ви скажете їм: «у пам’ять того, що вода Йордану розділилася перед ковчегом завіту Господа [всієї землі]; коли він переходив через Йордан, тоді вода Йордану розділилася»; таким чином камені ці будуть [у вас] для синів Ізраїлевих пам’ятником навік.","І зробили сини Ізраїлеві так, як наказав Ісус: взяли дванадцять каменів з Йордану, як говорив Господь Ісусові, за числом колін синів Ізраїлевих, і перенесли їх із собою на ночівлю, і поклали їх там.","І [інші] дванадцять каменів поставив Ісус серед Йордану на місці, де стояли ноги священиків, які несли ковчег завіту [Господнього]. Вони там і до цього дня.","Священики, які несли ковчег [завіту Господнього], стояли серед Йордану, доки не було закінчене [Ісусом] усе, що Господь повелів Ісусові сказати народу, — так, як заповідав Мойсей Ісусові; а народ тим часом поспіхом переходив.","Коли весь народ перейшов [Йордан], тоді перейшов і ковчег [завіту] Господнього, і священики перед народом;","і сини Рувима і сини Гада і половина коліна Манассіїного перейшли озброєними попереду синів Ізраїлевих, як говорив їм Мойсей.","Близько сорока тисяча озброєних на війну перейшло перед Господом на рівнини Єрихонські, щоб воювати.","У той день прославив Господь Ісуса перед очима всього Ізраїля і стали боятися його, як боялися Мойсея, в усі дні життя його.","І сказав Господь Ісусові, говорячи:","накажи священикам, які несуть ковчег одкровення, вийти з Йордану.","Ісус наказав священикам і сказав: вийдіть з Йордану.","І коли священики, які несли ковчег завіту Господнього, вийшли з Йордану, то, лиш тільки стопи ніг їхніх ступили на сушу, вода Йордану потекла по своєму місцю і пішла, як вчора і третього дня, вище всіх берегів своїх.","І вийшов народ з Йордану в десятий день першого місяця і поставив стан у Галгалі, на східній стороні Єрихона.","І дванадцять каменів, які взяли вони з Йордану, Ісус поклав у Галгалі","і сказав синам Ізраїлевим: коли запитають у наступний час сини ваші батьків своїх: «що означають ці камені?»,","скажіть синам вашим: «Ізраїль перейшов через Йордан цей по суші»,","бо Господь Бог ваш висушив води Йордану для вас, доки ви не перейшли його, так само, як Господь Бог ваш зробив з Червоним морем, яке висушив [Господь, Бог ваш,] перед нами, доки ми не перейшли його,","щоб усі народи землі знали, що рука Господня сильна, і щоб ви боялися Господа Бога вашого в усі дні."],"x":{"7":"5.3.13","12":"3.32.29","14":"5.3.7","19":"1.12.2","23":"1.14.21|25.77.13|25.113.3"}},{"v":["Коли всі царі аморрейські, які жили по цей бік Йордану до моря, і всі царі ханаанські, які біля моря, почули, що Господь [Бог] висушив води Йордану перед синами Ізраїлевими, доки переходили вони, тоді ослабло серце їхнє, [вони жахнулися] і не стало вже в них духу проти синів Ізраїлевих.","У той час сказав Господь Ісусові: зроби собі гострі [кам’яні] ножі й обріж синів Ізраїлевих удруге.","І зробив собі Ісус гострі [кам’яні] ножі й обрізав синів Ізраїлевих на [місці, названому]: Пагорб обрізання.","Ось причина, чому обрізав Ісус [синів Ізраїлевих, які тоді народилися на путі, і які з тих, що вийшли з Єгипту, не були тоді обрізані, всіх їх обрізав Ісус]: весь народ, який вийшов з Єгипту, чоловічої статі, усі здатні до війни померли в пустелі на путі, після виходу з Єгипту;","весь же народ, який вийшов, був обрізаний, але весь народ, що народився в пустелі на путі, після того, як вийшов з Єгипту, не був обрізаний;","бо сини Ізраїлеві сорок [два] роки ходили в пустелі [тому багато з них і не були обрізані], доки не перемер весь народ, здатний до війни, який вийшов з Єгипту, які не слухали голосу Господнього, і яким Господь клявся, що вони не побачать землі, яку Господь з клятвою обіцяв батькам їхнім, дати нам землю, де тече молоко і мед,","а замість їх породив синів їхніх. Цих обрізав Ісус, тому що вони були необрізані; тому що їх, [як народжених] на путі, не обрізували.","Коли весь народ був обрізаний, залишався він на своєму місці в стані, доки не видужав.","І сказав Господь Ісусові: нині Я зняв з вас посоромлення єгипетське. Чому і називається те місце «Галгал», навіть до цього дня.","І стояли сини Ізраїлеві станом у Галгалі і звершили Пасху у чотирнадцятий день місяця ввечері на рівнинах Єрихонських;","і на другий день Пасхи стали їсти з плодів землі цієї, опрісноки і сушені зерна в самий той день;","а манна перестала падати на другий день після того, як вони стали їсти плоди землі, і не було більше манни у синів Ізраїлевих, але вони їли в той рік плоди землі Ханаанської.","Ісус, знаходячись поблизу Єрихона, глянув, і бачить, і ось стоїть перед ним чоловік, і в руці його оголений меч. Ісус підійшов до нього і сказав йому: чи наш ти, чи з ворогів наших?","Він сказав: ні; я вождь воїнства Господнього, тепер прийшов [сюди]. Ісус упав лицем своїм на землю, і поклонився і сказав йому: що господар мій скаже рабові своєму?","Вождь воїнства Господнього сказав Ісусові: зніми взуття твоє з ніг твоїх, тому що місце, на якому ти стоїш, святе. Ісус так і зробив.","Єрихон замкнувся і був замкнений від страху синів Ізраїлевих: ніхто не виходив [з нього] і ніхто не входив."],"x":{"1":"4.11.25|5.2.9","2":"1.4.25","4":"3.14.23","6":"1.3.8","9":"0.34.14|1.16.3|38.4.15","10":"1.12.6","11":"2.2.14","12":"17.9.20","13":"1.23.23","14":"37.10.13|37.12.1","15":"1.3.5"}},{"v":["Тоді сказав Господь Ісусові: ось, Я віддаю в руки твої Єрихон і царя його, [і тих, що знаходяться в ньому,] людей сильних;","підіть навколо міста всі здатні до війни й обходьте місто один раз [на день]; і це роби шість днів;","і сім священиків нехай несуть сім труб ювілейних перед ковчегом; а в сьомий день обійдіть навколо міста сім разів, і священики нехай сурмлять трубами;","коли затрубить ювілейний ріг, коли почуєте звук труби, тоді весь народ нехай викликне гучним голосом, і стіна міста впаде до своєї основи, і [весь] народ піде [у місто, кинувшись] кожен зі своєї сторони.","І прикликав Ісус, син Навина, священиків [Ізраїлевих] і сказав їм: несіть ковчег завіту; а сім священиків нехай несуть сім труб ювілейних перед ковчегом Господнім.","І сказав [їм, щоб вони сказали] народу: підіть і обійдіть навколо міста; озброєні ж нехай ідуть перед ковчегом Господнім.","Як скоро Ісус сказав народу, сім священиків, які несли сім труб ювілейних перед Господом, пішли і засурмили [гучно] трубами, і ковчег завіту Господнього йшов за ними;","озброєні ж ішли попереду священиків, які сурмили трубами; а ті, що позаду, йшли за ковчегом [завіту Господнього] і під час ходу сурмили трубами.","Народу ж Ісус дав повеління і сказав: не викликуйте і не давайте чути голосу вашого, і щоб слово не виходило з уст ваших до того дня, доки я не скажу вам: «викликніть!» і тоді викликнете.","У такий спосіб ковчег [завіту] Господнього пішов навколо міста й обійшов один раз; і прийшли в стан і ночували в стані.","[На другий день] Ісус встав рано-вранці, і священики понесли ковчег [завіту] Господнього;","і сім священиків, які несли сім труб ювілейних перед ковчегом Господнім, ішли і сурмили трубами; озброєні ж ішли попереду них, а ті, що позаду, йшли за ковчегом [завіту] Господнього і, йдучи, сурмили трубами.","Таким чином і на другий день обійшли навколо міста один раз і повернулися в стан. І робили це шість днів.","В сьомий день встали рано, з появою зорі, і обійшли в такий самий спосіб навколо міста сім разів; тільки в цей день обійшли навколо міста сім разів.","Коли в сьомий раз священики сурмили трубами, Ісус сказав народу: викликніть, бо Господь віддав вам місто!","місто буде під закляттям, і все, що в ньому, — Господу [сил]; тільки Раав блудниця нехай залишиться в живих, вона і всякий, хто в її домі; тому що вона сховала посланих, яких ми посилали;","але ви бережіться заклятого, щоб і самим не піддатися закляттю, якщо візьмете що-небудь із заклятого, і щоб на стан [синів] Ізраїлевих не навести закляття і не зробити йому лиха;","і все срібло і золото, і сосуди мідні й залізні нехай будуть святинею Господу і ввійдуть у скарбницю Господню.","Народ викликнув, і засурмили трубами. Як тільки почув народ голос труби, викликнув народ [весь разом] гучним [і сильним] голосом, і впала [вся] стіна [міста] до своєї основи, і [весь] народ пішов у місто, кожен зі своєї сторони, і взяли місто.","І піддали закляттю усе, що в місті, і чоловіків і дружин, і молодих і старих, і волів, і овець, і ослів, [усе] знищили мечем.","А двом юнакам, які видивлялися землю, Ісус сказав: підіть у дім тієї блудниці і виведіть звідти її і всіх, які у неї, тому що ви поклялися їй.","І пішли юнаки, які видивлялися [місто, у дім жінки] і вивели Раав [блудницю] і батька її і матір її, і братів її, і всіх, які у неї були, і всіх родичів її вивели, і поставили їх поза станом Ізраїльським.","А місто й усе, що в ньому, спалили вогнем; тільки срібло і золото й сосуди мідні й залізні віддали, [щоб внести Господу] у скарбницю дому Господнього.","Раав же блудницю і дім батька її і всіх, які у неї були, Ісус залишив у живих, і вона живе серед Ізраїля до цього дня, тому що вона сховала посланих, яких посилав Ісус для вивідання Єрихона.","У той час Ісус поклявся і сказав: проклятий перед Господом той, хто відновить і побудує місто це Єрихон; на первістку своєму він покладе основу його і на молодшому своєму поставить ворота його. [Так і зробив Азан, родом з Вефиля: він на Авироні, первістку своєму, заснував його і на молодшому, врятованому, поставив ворота його.]","І Господь був з Ісусом, і слава його носилася по всій землі."],"x":{"1":"5.24.11","12":"5.3.1|5.7.16|5.8.10","16":"5.2.4","17":"2.27.28|4.7.26|5.7.5","18":"3.31.54","19":"75.11.30|22.12.15","20":"5.10.30","21":"5.2.14","22":"75.11.31","24":"50.1.5","25":"10.16.34"}},{"v":["Але сини Ізраїлеві зробили [великий] злочин [і взяли] із заклятого. Ахан, син Хармія, сина Завдія, сина Зари, з коліна Іудиного, взяв із заклятого, і гнів Господній запалав на синів Ізраїля.","Ісус з Єрихона послав людей у Гай, що біля Беф-Авена, зі східної сторони Вефиля, і сказав їм: підіть, огляньте землю. Вони пішли й оглянули Гай.","І повернувшись до Ісуса, сказали йому: не весь народ нехай іде, а нехай піде близько двох тисяч або близько трьох тисяч чоловік, і вразять Гай; усього народу не утруджуй туди, тому що їх мало [там].","Отже, пішло туди з народу близько трьох тисяч чоловік, але вони кинулися навтіки від жителів гайських;","жителі гайські убили з них до тридцяти шести чоловік, і переслідували їх від воріт до Севарима і розбили їх на спуску з гори; від чого серце народу розтануло і стало, як вода.","Ісус роздер одяг свій і упав лицем своїм на землю перед ковчегом Господнім і лежав до самого вечора, він і старійшини Ізраїлеві, і посипали порохом голови свої.","І сказав Ісус: о, Господи Владико! для чого Ти перевів народ цей через Йордан, щоб віддати нас у руки аморреїв і погубити нас? о, якби ми залишилися і жили за Йорданом!","О, Господи! що сказати мені після того, як Ізраїль показав спину ворогам своїм?","Хананеї і всі жителі землі почують і оточать нас і знищать ім’я наше з землі. І що зробиш тоді імені Твоєму великому?","Господь сказав Ісусові: встань, для чого ти упав на лице твоє?","Ізраїль згрішив, і переступили вони завіт Мій, який Я заповідав їм; і взяли із заклятого, й украли, і приховали, і поклали між своїми речами;","через те сини Ізраїлеві не могли встояти перед ворогами своїми і показали спини ворогам своїм, тому що вони підпали прокляттю; не буду більше з вами, якщо не знищите із середовища вашого проклятого.","Встань, освяти народ і скажи: освятіться до ранку, бо так говорить Господь Бог Ізраїлів: «закляте серед тебе, Ізраїлю; тому ти не можеш устояти перед ворогами твоїми, доки не віддалиш від себе заклятого»;","завтра підходьте [усі] за колінами вашими; коліно ж, яке вкаже Господь, нехай підходить за племенами; плем’я, яке вкаже Господь, нехай підходить за родинами; родина, яку вкаже Господь, нехай підходить по одній людині;","і викритого у викраденні заклятого нехай спалять вогнем, його й усе, що в нього, за те, що він переступив завіт Господній і зробив беззаконня серед Ізраїля.","Ісус, уставши рано-вранці, повелів підходити Ізраїлю за колінами його, і вказане коліно Іудине;","потім повелів підходити племенам Іуди, і вказане плем’я Зари; повелів підходити племені Зариному за родинами, і вказана [родина] Завдієва;","повелів підходити родині його по одній людині, і вказаний Ахан, син Хармія, сина Завдія, сина Зари, з коліна Іудиного.","Тоді Ісус сказав Ахану: сину мій! воздай славу Господу, Богу Ізраїлевому і зроби перед Ним сповідання й оголоси мені, що ти зробив; не приховай від мене.","У відповідь Ісусові Ахан сказав: дійсно, я згрішив перед Господом Богом Ізраїлевим і зробив те і те:","між здобиччю побачив я один чудовий сеннаарський одяг і двісті сиклів срібла і зливок золота вагою в п’ятдесят сиклів; це мені сподобалося і я взяв це; і ось, воно заховане в землі посеред намету мого, і срібло під ним [заховане].","Ісус послав людей, і вони побігли в намет [у стан]; і ось, усе це заховане було в наметі його, і срібло під ним.","Вони взяли це з намету і принесли до Ісуса і до всіх синів Ізраїлевих і поклали перед Господом.","Ісус і всі ізраїльтяни з ним взяли Ахана, сина Зариного, і срібло, і одяг, і зливок золота, і синів його і дочок його, і волів його й ослів його, і овець його і намет його, і все, що в нього було, і вивели їх [із усім] на долину Ахор.","І сказав Ісус: за те, що ти навів на нас лихо, Господь на тебе наводить лихо в день цей. І побили його всі ізраїльтяни камінням, і спалили їх вогнем, і накидали на них каміння.","І накидали на нього велику купу каміння, яка вціліла і до цього дня. Після цього затихла лють гніву Господнього. Тому те місце називається долиною Ахор навіть до цього дня."],"x":{"1":"5.22.20|12.2.7","2":"5.2.1","5":"5.8.5","6":"3.14.6|8.4.12|9.13.19","9":"1.32.12|3.14.13|39.2.17","13":"5.3.5|5.6.17","14":"8.10.20|26.16.33|42.1.7","15":"3.15.30|4.13.17|0.34.7","16":"5.8.10","19":"52.17.18|53.9.24|8.14.43","24":"5.22.20","25":"50.7.2|3.15.36","26":"9.18.17|31.65.10"}},{"v":["Господь сказав Ісусові: не бійся і не жахайся; візьми із собою весь народ, здатний до війни, і, вставши, піди до Гая; ось, Я віддаю в руки твої царя Гайського і народ його, місто його і землю його;","зроби з Гаєм і царем його те саме, що зробив ти з Єрихоном і царем його, тільки здобич його і худобу його розділіть собі; зроби засідку за містом.","Ісус і весь народ, здатний до війни, встав, щоб іти до Гая, і вибрав Ісус тридцять тисяч чоловік хоробрих і послав їх уночі,","і дав їм наказ і сказав: дивіться, ви будете складати засідку біля міста позаду міста; не відходьте далеко від міста і будьте всі готові;","а я і весь народ, який зі мною, підійдемо до міста; і коли [жителі Гая] виступлять проти нас, як і раніше, то ми побіжимо від них;","вони підуть за нами, так що ми відволічемо їх від міста; бо вони скажуть: «біжать від нас, як і раніше»; коли ми побіжимо від них,","тоді ви встаньте із засідки і заволодійте містом, і Господь Бог ваш віддасть його в руки ваші;","коли візьмете місто, запаліть місто вогнем, за словом Господнім зробіть; дивіться, я повеліваю вам.","Таким чином послав їх Ісус, і вони пішли в засідку і засіли між Вефилем і між Гаєм, із західного боку Гая; а Ісус у ту ніч ночував серед народу.","Вставши рано-вранці, Ісус оглянув народ, і пішов він і старійшини Ізраїлеві перед народом до Гая;","і весь народ, здатний до війни, який був з ним, пішов, наблизився і підійшов до міста [зі східного боку, засідка ж була на захід від міста],","і поставив стан з північної сторони Гая, а між ним і Гаєм була долина. Потім узяв він близько п’яти тисяч чоловік і посадив їх у засідці між Вефилем і Гаєм, із західного боку міста.","І народ розташував весь стан, який був з північного боку міста, так, що задня частина була з західного боку міста. І прийшов Ісус у ту ніч на середину долини.","Коли побачив це цар Гайський, негайно з жителями міста, вставши рано, виступив проти Ізраїля на бій, він і весь народ його, на призначене місце перед рівниною; а він не знав, що для нього є засідка позаду міста [його].","Ісус і весь Ізраїль, начебто вражені ними, побігли до пустелі;","а вони покликали весь народ, який був у місті, щоб переслідувати їх, і, переслідуючи Ісуса, віддалилися від міста;","у Гаї і Вефилі не залишилося жодної людини, яка не погналася б за Ізраїлем; і місто своє вони залишили відчиненим, переслідуючи Ізраїля.","Тоді Господь сказав Ісусові: простягни спис, що у руці твоїй, до Гая, бо Я віддам його в руки твої [і засідка негайно встане з місця свого]. Ісус простяг [руку свою і] спис, що був у його руці, до міста.","Ті, що сиділи у засідці, негайно встали з місця свого і побігли, як тільки він простяг руку свою, ввійшли в місто і взяли його і негайно запалили місто вогнем.","Жителі Гая, оглянувшись назад, побачили, що дим від міста піднімався до неба. І не було для них місця, куди б бігти — ні туди ні сюди; бо народ, який біг до пустелі, повернувся на переслідувачів.","Ісус і весь Ізраїль, побачивши, що ті, які сиділи в засідці, взяли місто, і дим від міста піднявся [до неба], повернулися і стали уражати жителів Гая;","а ті з міста вийшли назустріч їм, так що вони знаходилися всередині між ізраїльтянами, з яких одні були з того боку, а інші з іншого; так уражали їх, що не залишили жодного з них, хто уцілів би або втік;","а царя Гайського взяли живим і привели його до Ісуса.","Коли ізраїльтяни перебили всіх жителів Гая на полі, у пустелі, де вони переслідували їх, і коли усі вони до останнього впали від вістря меча, тоді всі ізраїльтяни повернулися до Гая і вразили його вістрям меча.","Полеглих у той день чоловіків і жінок, усіх жителів Гая, було дванадцять тисяч.","Ісус не опускав руки своєї, яку простяг зі списом, доки не піддав закляттю всіх жителів Гая;","тільки худобу і здобич міста цього [сини] Ізраїля розділили між собою, за словом Господа, як [Господь] сказав Ісусові.","І спалив Ісус Гай і обвернув його на вічні руїни, на пустелю, до цього дня;","а царя Гайського повісив на дереві, [і був він на дереві] до вечора; після заходу ж сонця наказав Ісус, і зняли труп його з дерева, і кинули його біля воріт міських, і накидали над ним велику купу каміння, яка вціліла навіть до цього дня.","Тоді Ісус влаштував жертовник Господу Богу Ізраїлевому на горі Гевал,","як заповів Мойсей, раб Господній, синам Ізраїлевим, про що написано в книзі закону Мойсея, — жертовник з каменів цільних, на які не піднімали заліза; і принесли на ньому всепалення Господу і звершили жертви мирні.","І написав [Ісус] там на каменях список із закону Мойсея, який він написав перед синами Ізраїлевими.","Весь Ізраїль, старійшини його і наглядачі [його] і судді його, стали з того й іншого боку ковчега навпроти священиків [і] левитів, які носять ковчег завіту Господнього, як прибульці, так і природні жителі, одна половина їх біля гори Гаризим, а друга половина біля гори Гевал, як раніше повелів Мойсей, раб Господній, благословляти народ Ізраїлів.","І потім прочитав [Ісус] усі слова закону, благословення і прокляття, як написано в книзі закону;","з усього, що Мойсей заповів [Ісусові], не було жодного слова, якого Ісус не прочитав би перед усім зібранням Ізраїля, [перед чоловіками,] і жінками, і дітьми, і прибульцями, які перебували серед них."],"x":{"1":"4.1.21|4.7.18|4.20.3","2":"5.6.20-21|6.20.29","4":"13.13.13","5":"5.7.4","6":"5.7.4","10":"5.6.12|5.7.16","22":"3.21.35|4.7.2","29":"4.21.23|9.18.17","31":"1.20.25|4.27.5","32":"4.17.18|4.27.3","33":"4.11.29|4.27.12-13|6.9.7","34":"4.28.1-2","35":"4.31.11"}},{"v":["Почувши це, всі царі [аморрейські], що за Йорданом, на горі і на рівнині і по всьому березі великого моря, [і які] біля Ливану, хеттеї, аморреї, [гергесеї,] хананеї, ферезеї, евеї та ієвусеї,","зібралися разом, щоб однодушно воювати з Ісусом та Ізраїлем.","Але жителі Гаваона, почувши, що Ісус зробив з Єрихоном і Гаєм,","вдалися до хитрости: пішли, запаслися хлібом на дорогу і поклали старі мішки на ослів своїх і старі, порвані і залатані міхи вина;","і взуття на ногах їхніх було старе з латками, і одяг на них старий; і весь дорожній хліб їхній був сухим і цвілим [і розкришеним].","Вони прийшли до Ісуса в стан [Ізраїльський] у Галгал і сказали йому і всім ізраїльтянам: ми прийшли з дуже далекої землі; отже, укладіть з нами союз.","Ізраїльтяни ж сказали евеям: можливо, ви живете біля нас? як нам укласти з вами союз?","Вони сказали Ісусові: ми раби твої. Ісус же сказав їм: хто ви і звідки прийшли?","Вони сказали йому: з дуже далекої землі прийшли раби твої в ім’я Господа Бога твого; бо ми чули славу Його й усе, що зробив Він у Єгипті,","й усе, що Він зробив двом царям аморрейським, які [були] по той бік Йордану, Сигону, царю Есевонському, та Огу, царю Васанському, який [жив] в Астарофі [й Едреї].","[Чуючи це,] старійшини наші і всі жителі нашої землі сказали нам: візьміть у руки ваші хліба на дорогу і підіть назустріч їм і скажіть їм: «ми раби ваші; отже, укладіть з нами союз».","Цей хліб наш з домів наших ми взяли теплим у той день, коли пішли до вас, а тепер ось, він зробився сухим і цвілим;","і ці міхи з вином, які ми налили нові, ось, порвалися; і цей одяг наш і взуття наше постаріли від дуже далекої дороги.","Ізраїльтяни взяли їхнього хліба, а Господа не запитали.","І уклав Ісус з ними мир і ухвалив з ними умову в тім, що він збереже їм життя; і поклялись їм начальники громади.","А через три дні, як уклали вони з ними союз, почули, що вони сусіди їхні і живуть поблизу них;","бо сини Ізраїлеві, вирушивши у дорогу, прийшли в міста їхні на третій день; міста ж їхні [були]: Гаваон, Кефира, Беероф і Кириаф-Іарим.","[Ісус і] сини Ізраїлеві не побили їх, тому що [усі] начальники громади клялися їм Господом Богом Ізраїлевим. За це вся громада [Ізраїлева] обурилася на начальників.","Усі начальники сказали всій громаді: ми клялися їм Господом Богом Ізраїлевим і тому не можемо торкнутися їх;","а ось що зробимо з ними: залишимо їх живими, щоб не впав на нас гнів за клятву, якою ми клялися їм.","І сказали їм начальники: нехай вони живуть, але будуть рубати дрова і черпати воду для всієї громади. [І зробила вся громада] так, як сказали їм начальники.","Ісус покликав їх і сказав: для чого ви обдурили нас, сказавши: «ми дуже далеко від вас», тоді як ви живете поблизу нас?","за це прокляті ви! без кінця ви будете рабами, будете рубати дрова і черпати воду для [мене і для] дому Бога мого]!","Вони у відповідь Ісусові сказали: дійшло до відома рабів твоїх, що Господь Бог твій повелів Мойсеєві, рабові Своєму, дати вам усю землю і знищити [нас і] всіх жителів цієї землі перед лицем вашим; тому ми дуже боялися, щоб ви не позбавили нас життя, і зробили цю справу;","тепер ось ми в руці твоїй: як краще і справедливіше тобі здасться вчинити з нами, так і вчини.","І вчинив з ними так: визволив їх від руки синів Ізраїлевих, і вони не умертвили їх;","і визначив у той день Ісус, щоб вони рубали дрова і черпали воду для [всієї] громади і для жертовника Господнього; [тому жителі Гаваона зробилися дроворубами і водоносами для жертовника Божого] навіть до цього дня, на місці, яке б не обрав [Господь]."],"x":{"1":"5.3.10","3":"9.2.12|10.3.4","6":"5.5.9","7":"1.23.32|4.7.2","10":"3.21.24","14":"1.25.22|3.27.21|8.23.9","17":"5.18.25|12.2.50","18":"5.11.19","20":"9.21.1-2|10.9.21","23":"17.10.28","24":"4.7.2","26":"5.11.19","27":"12.9.2|13.2.18|14.8.20"}},{"v":["Коли Адониседек, цар Єрусалимський, почув, що Ісус узяв Гай і піддав його закляттю, і що так само вчинив з Гаєм і царем його, як вчинив з Єрихоном і царем його, і що жителі Гаваона уклали мир [з Ісусом і] з Ізраїлем і залишилися серед них,","тоді він дуже злякався, тому що Гаваон [було] місто велике, як одне з царських міст, і більше Гая, і всі жителі його люди хоробрі.","Тому Адониседек, цар Єрусалимський, послав до Гогама, царя Хевронського, і до Фирама, царя Іармуфського, і до Яфія, царя Лахисського, і до Девира, царя Еглонського, щоб сказати:","прийдіть до мене і допоможіть мені уразити Гаваон за те, що він уклав мир з Ісусом і синами Ізраїлевими.","Вони зібралися, і пішли п’ять царів аморрейських: цар Єрусалимський, цар Хевронський, цар Іармуфський, цар Лахисський, цар Еглонський, вони і все ополчення їх, і розташувалися станом біля Гаваона, щоб воювати проти нього.","Жителі Гаваона послали до Ісуса в стан [ізраїльський], у Галгал, сказати: не відніми руки твоєї від рабів твоїх; прийди до нас скоріше, врятуй нас і подай нам допомогу; тому що зібралися проти нас усі царі аморрейські, які живуть в горах.","Ісус пішов з Галгала сам, і з ним весь народ, здатний до війни, і всі чоловіки хоробрі.","І сказав Господь Ісусові: не бійся їх, бо Я віддав їх у руки твої: ніхто з них не устоїть перед лицем твоїм.","І прийшов на них Ісус раптово, [тому що] усю ніч ішов він з Галгала.","Господь привів їх у сум’яття, коли ті побачили ізраїльтян, і вони вразили їх у Гаваоні сильною поразкою, і переслідували їх по дорозі до узвишшя Вефорона, й уражали їх до Азека і до Македа.","Коли ж вони бігли від ізраїльтян по схилу гори Вефоронської, Господь кидав на них з небес великі камені [граду] до самого Азека, і вони вмирали; більше було тих, які померли від каміння граду, ніж тих, яких умертвили сини Ізраїлеві мечем [у бою].","Ісус воззвав до Господа в той день, в який віддав Господь [Бог] Аморрея в руки Ізраїля, коли побив їх у Гаваоні, і вони побиті були перед лицем синів Ізраїлевих, і сказав перед ізраїльтянами: стій, сонце, над Гаваоном, і місяць, над долиною Аїалонською!","І зупинилося сонце, і місяць стояв, доки народ мстився ворогам своїм. Чи не це написано в книзі Праведного: «стояло сонце серед неба і не поспішало до заходу майже цілий день»?","І не було такого дня ні раніше ні після того, в який Господь [так] слухав би голосу людського. Тому що Господь боровся за Ізраїля.","Потім повернувся Ісус і весь Ізраїль з ним у стан, у Галгал.","А ті п’ять царів втекли і сховалися в печері в Македі.","Коли донесено було Ісусові і сказано: «знайшлися п’ять царів, вони ховаються в печері в Македі»,","Ісус сказав: «приваліть великі камені до отвору печери і приставте до неї людей стерегти їх;","а ви не зупиняйтеся [тут], але переслідуйте ворогів ваших і знищуйте задню частину війська їх і не давайте їм ввійти в міста їх, бо Господь Бог ваш ввіддав їх у руки ваші».","Після того, як Ісус і сини Ізраїлеві зовсім уразили їх дуже великою поразкою, і ті з них, що залишилися, утекли в укріплені міста,","весь народ повернувся в стан до Ісуса в Макед з миром, і ніхто на синів Ізраїлевих не поворухнув язиком своїм.","Тоді Ісус сказав: відкрийте отвір печери і виведіть до мене з печери п’ятьох царів тих.","Так і зробили: вивели до нього з печери п’ятьох царів тих: царя Єрусалимського, царя Хевронського, царя Іармуфського, царя Лахисського і царя Еглонського.","Коли вивели царів цих до Ісуса, Ісус покликав усіх ізраїльтян і сказав начальникам воїнів, які ходили з ним: підійдіть, наступіть ногами вашими на шиї царів цих. Вони підійшли і наступили ногами своїми на шиї їхні.","Ісус сказав їм: не бійтеся і не жахайтеся, будьте твердими і мужніми; бо так вчинить Господь з усіма ворогами вашими, з якими будете воювати.","Потім уразив їх Ісус і вбив їх і повісив їх на п’ятьох деревах; і висіли вони на деревах до вечора.","При заході сонця наказав Ісус, і зняли їх з дерев, і кинули їх у печеру, в якій вони ховалися, і привалили великі камені до отвору печери, які там навіть до цього дня.","У той самий день узяв Ісус Макед, і уразив [його] мечем і царя його, і піддав закляттю їх і все, що дихає, що знаходилося в ньому: нікого не залишив, хто вцілів би [й уник]; і вчинив з царем Македським так само, як учинив з царем Єрихонським.","І пішов Ісус і всі ізраїльтяни з ним з Македа до Ливни і воював проти Ливни;","і віддав Господь і її в руки Ізраїля, [і взяли її] і царя її, і знищив її Ісус мечем і все, що дихає, що знаходилося в ній: нікого не залишив у ній, хто вцілів би [й уник], і вчинив з царем її так само, як учинив з царем Єрихонським.","З Ливни пішов Ісус і всі ізраїльтяни з ним до Лахиса і розташувався біля нього станом і воював проти нього;","і віддав Господь Лахис у руки Ізраїля, і взяв він його на другий день, і вразив його мечем і все, що дихає, що було в ньому, [і знищив його] так, як учинив з Ливною.","Тоді прийшов на допомогу Лахису Горам, цар Газерський; але Ісус уразив його і народ його [мечем] так, що нікого у нього не залишив, хто уцілів би [й уник].","І пішов Ісус і всі ізраїльтяни з ним з Лахиса до Еглона і розташувалися поряд нього станом і воювали проти нього;","[і віддав його Господь у руки Ізраїля,] і взяли його в той самий день і вразили його мечем, і все, що дихає, що знаходилося в ньому в той день, піддав він закляттю, як учинив з Лахисом.","І пішов Ісус і всі ізраїльтяни з ним з Еглона до Хеврона і воювали проти нього;","і взяли його й уразили його мечем, і царя його, і всі міста його, і все, що дихає, що знаходилося в ньому; нікого не залишив, хто уцілів би, як учинив він і з Еглоном: піддав закляттю його і все, що дихає, що знаходилося в ньому.","Потім обернувся Ісус і весь Ізраїль з ним до Давира і воював проти нього;","і взяв його і царя його, і всі міста його, й уразили їх мечем, і піддали закляттю [їх і] все, що дихає, що знаходилося в ньому: нікого не залишилося, хто вцілів би; як учинив з Хевроном і царем його, так учинив з Давиром і царем його, і як учинив з Ливною і царем її.","І вразив Ісус усю землю нагірну і полуденну, і низинні місця і землю, що лежить біля гір, і всіх царів їх: нікого не залишив, хто вцілів би, і все, що дихає, піддав закляттю, як повелів Господь Бог Ізраїлів;","уразив їх Ісус від Кадес-Варні до Гази, і всю землю Гошен навіть до Гаваона;","і всіх царів цих і землі їх Ісус узяв одним разом, бо Господь Бог Ізраїлів боровся за Ізраїля.","Потім Ісус і всі ізраїльтяни з ним повернулися в стан, у Галгал."],"x":{"8":"5.11.6|5.24.11","9":"5.11.7","10":"1.23.27|4.11.25|10.9.17","11":"31.28.21|29.5.23|30.46.6","12":"31.28.21|30.46.5","13":"11.20.11|31.28.21|9.1.18","14":"1.14.14:25|4.1.30","19":"4.25.18","24":"0.3.15|52.10.19|62.16.20","26":"4.21.23|5.8.29","27":"4.21.23|5.8.29","28":"4.20.16|5.6.20","32":"5.15.39|3.21.35","33":"10.9.15|5.8.22|5.11.8","38":"5.13.26","40":"5.12.8|4.7.2|4.20.16|1.23.32|1.34.12","42":"1.14.14|4.1.30|4.3.22"}},{"v":["Почувши це, Іавин, цар Асорський, послав до Іовава, царя Мадонського, і до царя Шимронського, і до царя Ахсафського,","і до царів, які жили на півночі на горі і на рівнині з південної сторони Хиннарофа, і на низинних місцях, і в Нафоф-Дорі на захід,","до хананеян, які жили на сході і до моря, до аморреян і хеттеян, до ферезеян і до ієвусеян, які жили на горі, і до евеян, які жили біля Ермона в землі Массифі.","І виступили вони і все ополчення їх з ними, численний народ, який безліччю дорівнював піску на березі морському; і коней і колісниць було дуже багато.","І зібралися всі царі ці, і прийшли і розташувалися станом разом біля вод Меромських, щоб воювати з Ізраїлем.","Але Господь сказав Ісусові: не бійся їх, тому що завтра, близько цього часу, Я віддам усіх [їх] на знищення [синам] Ізраїля; коням же їхнім переріж жили і колісниці їхні спали вогнем.","Ісус і з ним весь народ, здатний до війни, раптово вийшли на них до вод Меромських і напали на них.","І віддав їх Господь у руки ізраїльтян, і уразили вони їх, і переслідували їх до Сидона великого і до Мисрефоф-Маїма, і до долини Мицфи на схід, і перебили їх, так що нікого з них не залишилося, хто вцілів би [й уник].","І вчинив Ісус з ними так, як сказав йому Господь: коням їхнім перерізав жили і колісниці їхні спалив вогнем.","У той же час, повернувшись, Ісус узяв Асор і царя його убив мечем [Асор же раніше був главою всіх царств цих];","і побили все, що дихає, що було в ньому, мечем, [усе] піддавши закляттю: не залишилося жодної душі; а Асор він спалив вогнем.","І всі міста царів цих і всіх царів їх узяв Ісус і убив мечем, піддавши їх закляттю, як повелів Мойсей, раб Господній;","утім, усіх міст, що лежали на височині, не палили ізраїльтяни, крім одного Асора, який спалив Ісус.","А всю здобич міст цих і [всю] худобу розграбували сини Ізраїлеві собі; людей же всіх перебили мечем, так що знищили всіх їх: не залишили [з них] жодної душі.","Як повелів Господь Мойсеєві, рабові Своєму, так Мойсей заповів Ісусові, а Ісус так і зробив: не відступив від жодного слова в усьому, що повелів Господь Мойсеєві.","Таким чином Ісус узяв усю цю нагірну землю, всю землю полуденну, всю землю Гошен і низинні місця, і рівнину і гору Ізраїлеву, і низинні місця [біля гори],","від гори Халак, що простягається до Сеїру, до Ваал-Гада в долині Ливанській, біля гори Ермон, і всіх царів їх узяв, уразив їх і убив.","Довгий час вів Ісус війну з усіма цими царями.","Не було [жодного] міста, яке уклало б мир із синами Ізраїлевими, крім евеян, жителів Гаваона: все узяли вони війною;","бо від Господа було те, що вони озлобили серце своє і війною зустрічали Ізраїля — для того, щоб піддані були закляттю і щоб не було їм помилування, але щоб знищені були так, як повелів Господь Мойсеєві.","У той же час прийшов Ісус і уразив [усіх] єнакимян на горі, у Хевроні, у Давирі, в Анаві, на всій горі Іудиній і на всій горі Ізраїлевій; з містами їх віддав їх Ісус закляттю;","не залишилося [жодного] з єнакимян у землі синів Ізраїлевих, залишилися тільки в Газі, у Гефі та в Азоті.","Таким чином узяв Ісус усю землю, як говорив Господь Мойсеєві, і віддав її Ісусові в наділ ізраїльтянам, за розподілом між колінами їх. І заспокоїлася земля від війни."],"x":{"1":"11.15.29","2":"52.5.1","3":"5.6.1|5.24.11","4":"21.11.1","6":"5.10.8","8":"5.24.11|0.10.15","10":"10.9.15|32.49.28","11":"3.33.52|4.20.16|6.4.2","12":"3.33.52-53|4.7.2","15":"1.34.11","16":"5.10.41","19":"5.9.18","20":"5.24.12","21":"3.13.23","22":"32.47.5|9.21.20|8.17.4","23":"5.14.15"}},{"v":["Ось царі тієї землі, яких уразили сини Ізраїлеві і землю яких взяли в спадщину по той бік Йордану до сходу сонця, від потоку Арнона до гори Ермона, і всю рівнину на схід:","Сигон, цар Аморрейський, що жив у Есевоні, який володів від Ароера, що біля берега потоку Арнона, і від середини потоку, половиною Галаада, до потоку Іавока, межі аммонитян,","і рівниною до самого моря Хиннерефського до сходу і до моря рівнини, моря Солоного, на схід по дорозі до Беф-Ієшимофу, а до півдня місцями, що лежать біля підошви Фасги;","суміжний йому Ог, цар Васанський, останній з рефаїмів, який жив в Астарофі та в Едреї,","який володів горою Ермоном і Салхою й усім Васаном, до межі Гессурської і Маахської, і половиною Галаада, до межі Сигона, царя Есевонського.","Мойсей, раб Господній, і сини Ізраїлеві убили їх; і дав її Мойсей, раб Господній, у спадщину коліну Рувимовому і Гадовому і половині коліна Манассіїного.","І ось царі [аморрейської] землі, яких уразив Ісус і сини Ізраїлеві по цей бік Йордану на захід, від Ваал-Гада в долині Ливанській до Халака, гори, що простягається до Сеїру, яку віддав Ісус колінам Ізраїлевим у спадщину, за розподілом їх,","на горі, на низинних місцях, на рівнині, на місцях, що лежать біля гір, і в пустелі і на півдні, хеттеїв, аморреїв, хананеїв, ферезеїв, евеїв та ієвусеїв:","один цар Єрихона, один цар Гая, що біля Вефиля,","один цар Єрусалима, один цар Хеврона,","один цар Іармуфа, один цар Лахиса,","один цар Еглона, один цар Газера,","один цар Давира, один цар Гадера,","один цар Хорми, один цар Арада,","один цар Ливни, один цар Одоллама,","один цар Македа, один цар Вефиля,","один цар Таппуаха, один цар Хефера.","Один цар Афека, один цар Шарона,","один цар Мадона, один цар Асора,","один цар Шимрон-Мерона, один цар Ахсафа,","один цар Фаанаха, один цар Мегиддона,","один цар Кедеса, один цар Іокнеама біля Кармила,","один цар Дора біля Нафаф-Дорі, один цар Гоїма в Галгалі,","один цар Фирци. Усіх царів тридцять один."],"x":{"1":"3.21.13","2":"3.21.24|31.16.2|0.32.22","3":"3.33.49|3.34.11|0.14.3","4":"5.13.12|4.1.4","5":"4.3.13|8.27.8","6":"3.21.24|3.32.33","7":"5.10.40","9":"5.6.1|5.8.29","10":"5.10.1","11":"5.10.3","12":"5.10.33","13":"5.10.39","16":"5.10.28","17":"10.4.10","20":"5.11.1"}},{"v":["Коли Ісус постарів, увійшов у літа похилі, тоді Господь сказав йому: ти постарів, увійшов у літа похилі, а землі брати в спадщину залишається ще дуже багато.","Залишається ця земля: всі округи филистимські і вся земля Гессурська [і Хананейська].","Від Сихора, що перед Єгиптом, до меж Екрона на півночі, вважаються ханаанськими п’ять власників филистимських: Газький, Азотський, Аскалонський, Гефський, Екронський і Аввейський;","на південь же уся земля ханаанська від Меари Сидонської до Афека, до меж аморрейських,","також [филистимська] земля Гевла і весь Ливан до сходу сонця від Ваал-Гада, що поряд гори Ермона, до входу в Емаф.","Усіх гірських жителів від Ливану до Мисрефоф-Маїма, усіх сидонян Я прожену від лиця синів Ізраїлевих. Розділи ж її в наділи Ізраїлю, як Я повелів тобі;","розділи землю цю в наділи дев’ятьом колінам і половині коліна Манассіїного [від Йордану до моря великого на захід віддай її їм; велике море буде межею].","А коліно Рувимове і Гадове з другою половиною коліна Манассіїного одержали наділи свої від Мойсея за Йорданом на схід [сонця], як дав їм Мойсей, раб Господній,","від Ароера, що на березі потоку Арнона, і місто, що серед потоку, і всю рівнину Медеву до Дивона;","також усі міста Сигона, царя Аморрейського, що царював у Есевоні, до меж аммонитських,","також Галаад і область Гессурську і Маахську, і всю гору Ермон і весь Васан до Салхи,","усе царство Ога Васанського, який царював у Астарофі та в Едреї. Він залишався один з рефаїмів, яких Мойсей уразив і прогнав.","Але сини Ізраїлеві не вигнали жителів Гессура і Маахи [і хананеян], і живуть Гессур і Мааха серед Ізраїля до цього дня.","Тільки коліну Левіїному не дав він частки: жертви Господа Бога Ізраїлевого є наділ його, як сказав йому Господь. [Ось розподіл, який зробив Мойсей синам Ізраїлевим за племенами їх на рівнинах моавитських за Йорданом, навпроти Єрихона:]","коліну синів Рувимових за племенами їх дав наділ Мойсей:","межею їх був Ароер, що на березі потоку Арнона, і місто, що серед потоку, і вся рівнина біля Медеви,","Есевон і всі міста його, що на рівнині, і Дивон, Вамоф-Ваали Беф-Ваал-Меон,","Іааца, Кедемоф і Мефааф,","Кириафаїм, Сивма і Цереф-Шахар на горі Емек,","Беф-Фегор і місця біля підошві Фасги і Беф-Ієшимоф,","і всі міста на рівнині, і все царство Сигона, царя Аморрейського, який царював у Есевоні, якого убив Мойсей, так само як і вождів мадіамських: Евія, і Рекема, і Цура, і Хура, і Реву, князів сигонових, що жили на землі [тій];","також Валаама, сина Веорового, віщуна, убили сини Ізраїлеві мечем у числі вбитих ними.","Межею синів Рувимових був Йордан. Ось наділи синів Рувимових за племенами їх, міста і села їх.","Мойсей дав також наділ коліну Гадовому, синам Гадовим, за племенами їх:","межею їх були Іазер і всі міста галаадські, і половина землі синів Аммонових до Ароера, що перед Раввою,","і землі від Есевона до Рамаф-Мицфи і Ветонима і від Маханаїма до меж Давира,","і на долині Беф-Гарам і Беф-Нимра і Сокхоф і Цафон, залишок царства Сигона, царя Есевонського; межею його був Йордан до моря Хиннерефського за Йорданом на схід.","Ось наділ синів Гадових за племенами їх, міста і села їх.","Мойсей дав наділ і половині коліна Манассіїного, що належав половині коліна синів Манассіїних, за племенами їх;","наділ їх був: від Маханаїма весь Васан, усе царство Ога, царя Васанського, і всі селища Іаїрові, що у Васані, шістдесят міст;","а половина Галаада й Астароф і Едрея, царствені міста Ога Васанського, [надані] синам Махира, сина Манассіїного, половині синів Махирових, за племенами їх.","Ось що Мойсей дав у наділ на рівнинах моавитських за Йорданом навпроти Єрихона на схід.","Але коліну Левіїному Мойсей не дав наділу: Господь Бог Ізраїлів Сам є наділом їх, як Він говорив їм."],"x":{"3":"32.2.18","5":"10.5.18|25.82.8","6":"25.77.55","8":"3.32.33|5.22.4","9":"4.2.36|5.12.2","12":"0.14.15|3.21.33","14":"3.18.20|4.10.9|4.18.2|36.44.28|75.7.5","16":"9.24.5|31.15.2","17":"31.15.2","19":"31.16.8","21":"3.31.8","22":"3.22.5|3.24.25|3.31.8","25":"6.5.17|9.11.1","26":"9.2.8|5.10.38","27":"31.15.6","30":"3.32.41","33":"3.18.20"}},{"v":["Ось що одержали в наділ сини Ізраїлеві в землі Ханаанській, що розділили їм у наділ Єлеазар священик та Ісус, син Навина, і начальники поколінь у колінах синів Ізраїлевих;","за жеребом ділили вони, як повелів Господь через Мойсея, дев’ятьом колінам і половині коліна [Манассіїного],","бо двом колінам і половині коліна [Манассіїного] Мойсей дав наділ за Йорданом, левитам же не дав наділу між ними;","бо від синів Йосифових народилися два коліна: Манассіїне і Єфремове; тому вони і не дали левитам частини в землі, [а тільки] міста для проживання з околицями їх для худоби їхньої і для інших потреб їхніх.","Як повелів Господь Мойсеєві, так і зробили сини Ізраїлеві, коли ділили на наділи землю.","Сини Іудині прийшли в Галгал до Ісуса. І сказав йому Халев, син Ієфоннії, кенезеянин: ти знаєш, що говорив Господь Мойсеєві, чоловіку Божому, про мене і про тебе в Кадес-Варні;","я був сорока років, коли Мойсей, раб Господній, посилав мене з Кадес-Варні оглянути землю, і я приніс йому у відповідь, що було в мене на серці:","брати мої, які ходили зі мною, привели у страх серце народу, а я ретельно додержувався Господа Бога мого;","і клявся Мойсей у той день і сказав: «земля, по якій ходила нога твоя, буде наділом тобі і дітям твоїм навік, тому що ти достеменно пішов за Господом Богом моїм»;","отже, ось, Господь зберіг мене в живих, як Він говорив; уже сорок п’ять років минуло від того часу, коли Господь сказав Мойсеєві слово це, й Ізраїль ходив по пустелі; тепер, ось, мені вісімдесят п’ять років;","але і нині я настільки ж міцний, як і тоді, коли посилав мене Мойсей: скільки тоді було в мене сили, стільки і тепер є для того, щоб воювати і виходити і входити;","отже, дай мені цю гору, про яку говорив Господь у той день; бо ти чув у той день, що там [живуть] сини Єнакові, і міста у них великі й укріплені; можливо, Господь [буде] зі мною, і я вижену їх, як говорив Господь.","Ісус благословив його, і дав у наділ Халеву, синові Ієфонніїному, [кенезеянину,] Хеврон.","Таким чином Хеврон залишився наділом Халева, сина Ієфонніїного, кенезеянина, до цього дня, за те, що він справді пішов за [повелінням] Господа Бога Ізраїлевого.","Ім’я Хеврону раніше було Кириаф-Арби, як називався між синами Єнака один чоловік великий. І земля заспокоїлася від війни."],"x":{"1":"3.34.2:17","2":"3.34.13|54.13.19","3":"3.18.20|3.32.33|4.3.12|4.10.9|5.13.14","4":"3.35.3","5":"3.34.16","6":"3.14.24","7":"3.13.7:17","8":"3.13.31:33|3.14.6","9":"5.1.3","11":"4.34.7|30.46.11","13":"3.14.24|6.1.20|21.2.56"}},{"v":["Жереб коліну синів Іудиних, за племенами їх, випав такий: у суміжності з Ідумеєю була пустеля Син, на південь, у кінці Фемана;","південною межею їх був край моря Солоного від затоки, що простягається на південь;","на півдні йде він до височини Акраввимської, проходить Цин і, піднімаючись з південного боку до Кадес-Варні, проходить Хецрон і, піднімаючись до Аддара, [йде по західній стороні Кадеса,] повертає до Каркаї,","потім проходить Ацмон, іде до потоку Єгипетського, так що кінцем цієї межі є море. Це буде південна ваша межа.","Межею же на схід [усе] море Солоне, до гирла Йордану; а межа з північного боку починається від затоки моря, від гирла Йордану;","звідси межа піднімається до Беф-Хогли і проходить з північної сторони до Беф-Арави, і йде межа вгору до каменя Богана, сина Рувимового;","потім піднімається межа до Давира від долини Ахор і на півночі повертає до Галгала, який навпроти узвишшя Адуммима, що лежить з південної сторони потоку; звідси межа проходить до вод Ен-Шемеша і закінчується біля Ен-Рогела;","звідси межа йде вгору до долини сина Енномового з південного боку Ієвуса, який є Єрусалим, і піднімається межа на вершину гори, що на заході навпроти долини Енномової, що на краю долини рефаїмів з півночі;","від вершини гори межа повертає до джерела вод Нефтоах і йде до міст гори Ефрона, і повертає межа до Ваала, який є Кириаф-Іарим;","потім повертає межа від Ваала до моря [і йде] до гори Сеїру, і йде північною стороною гори Ієарим, яка є Кесалон, і, сходячи до Вефсамиса, проходить через Фимну;","звідси межа йде північною стороною Екрона, і повертає межа до Шикарона, проходить через гору [землі] Ваал і доходить до Іавнеїла, і закінчується межа біля моря. Західна межа являє собою велике море.","Ось межа синів Іудиних із племенами їх з усіх боків.","І Халеву, синові Ієфонніїному, [Ісус] дав частину серед синів Іудиних, як повелів Господь Ісусові; [і дав йому Ісус] Кириаф-Арби, батька Єнакового, інакше Хеврон.","І вигнав звідти Халев [син Ієфонніїн] трьох синів Єнакових: Шешая, Ахимана і Фалмая, дітей Єнакових.","Звідси [Халев] пішов проти жителів Давира [ім’я Давиру раніше було Кириаф-Сефер].","І сказав Халев: хто вразить Кириаф-Сефер і візьме його, тому віддам Ахсу, дочку мою, за дружину.","І взяв його Гофониїл, [молодший] син Кеназа, брата Халевового, і віддав він за дружину йому Ахсу, дочку свою.","Коли належало їй іти, її навчили просити в батька її поле, і вона зійшла з осла. Халев сказав їй: що тобі?","Вона сказала: дай мені благословення; ти дав мені землю полуденну, дай мені і джерела вод. І дав він їй джерела верхні і джерела нижні.","Ось наділ коліна синів Іудиних, за племенами їх:","міста з краю коліна синів Іудиних у суміжності з Ідумеєю на півдні були: Кавцеїл, Едер та Іагур,","Кина, Димона, Адада,","Кедес, Асор та Іфнан,","Зиф, Телем і Валоф,","Гацор-Хадафа, Кириаф, Хецрон, інакше Гацор,","Амам, Шема і Молада,","Хацар-Гадда, Хешмон і Веф-Палет,","Хацар-Шуал, Вирсавія і Визиофея, [і села їх і передмістя їх,]","Ваала, Іїм і Ацем,","Елфолад, Кесил і Хорма,","Циклаг, Мадмана і Сансана,","Леваоф, Шелихим, Аїн і Риммон: усіх двадцять дев’ять міст із їх селами.","На низинних місцях: Ештаол, Цора й Ашна,","Заноах, Ен-Ганним, Таппуах і Гаенам,","Іармуф, Одоллам, [Немра,] Сохо й Азека,","Шаараїм, Адифаїм, Гедера або Гедерофаїм: чотирнадцять міст із їх селами.","Ценан, Хадаша, Мигдал-Гад,","Дилеан, Мицфе та Іокфеїл,","Лахис, Воцкаф і Еглон,","Хаббон, Лахмас і Хифлис,","Гедероф, Беф-Дагон, Наема і Макед: шістнадцять міст із їх селами.","Ливна, Ефер і Ашан,","Іффах, Ашна і Нецив,","Кеїла, Ахзив і Мареша [й Едом]: дев’ять міст із їх селами.","Екрон із залежними від нього містами і селами його,","і від Екрона до моря все, що знаходиться біля Азота, із селами їх,","Азот, залежні від нього міста і села його, Газа, залежні від неї міста і села її, до самого потоку Єгипетського і великого моря, яке є межа.","На горах: Шамир, Іаттир і Сохо,","Данна, Кириаф-Санна, інакше Давир,","Анаф, Ештемо й Аним,","Гошен, Холон і Гило: одинадцять міст із їх селами.","Арав, Дума й Ешан,","Іанум, Беф-Таппуах і Афека,","Хумта, Кириаф-Арби, інакше Хеврон, і Цигор: дев’ять міст із їх селами.","Маон, Кармил, Зиф і Юта,","Ізреель, Іокдам і Заноах,","Каїн, Гива і Фимна: десять міст із їх селами.","Халхул, Беф-Цур і Гедор,","Маараф, Беф-Аноф і Елтекон: шість міст із їх селами. [Феко, Ефрафа, інакше Вифлеєм, Фагор, Етам, Кулон, Татамі, Сорес, Карем, Галлим, Вефир і Манохо: одинадцять міст із їх селами.]","Кириаф-Ваал, інакше Кириаф-Іарим, і Аравва: два міста із їх селами [і передмістями].","У пустелі: Беф-Арава, Миддин і Секаха,","Нившан, Ір-Мелах і Ен-Геди: шість міст із їх селами.","Але ієвусеян, жителів Єрусалима, не могли вигнати сини Іудини, і тому ієвусеяни живуть із синами Іуди в Єрусалимі навіть до цього дня."],"x":{"1":"3.34.3","2":"5.18.19","3":"0.14.7|3.34.4","4":"3.34.5","6":"5.18.17","8":"17.11.4|5.18.14-15","10":"5.21.16|8.6.12|11.14.11","13":"5.14.13","14":"6.1.10","16":"8.18.25|6.1.12-13","19":"0.33.11","21":"17.11.25","25":"9.13.23","32":"48.14.10|5.19.6-7","33":"5.19.41","35":"43.1.15","39":"5.10.32|11.14.19","42":"5.10.29","44":"5.19.29|13.14.9","45":"11.1.2","47":"3.34.6","51":"5.10.41","55":"8.23.25","60":"5.18.14","62":"13.20.2","63":"6.1.8|9.5.6"}},{"v":["Потім випав жереб синам Йосифа: від Йордану поблизу Єрихона, біля вод Єрихонських на схід, пустеля, що простягається від Єрихона до гори Вефильської;","від Вефиля йде межа до Луза і переходить до межі Архи до Атарофа,","і спускається до моря, до межі Іафлета, до межі нижнього Беф-Орона і до Газера, і закінчується біля моря.","Це одержали в наділ сини Йосифа: Манассія та Єфрем.","Межа синів Єфремових за племенами їх була ця: від сходу межею наділу їх був Атароф-Адар до Беф-Орона верхнього [і Газари];","потім іде межа до моря північним боком Михмефафа і повертає до східного боку Фаанаф-Силома і проходить його зі східної сторони Іаноха;","від Іаноха, сходячи до Атарофа і Наарафа, примикає до Єрихона і доходить до Йордану;","від Таппуаха йде межа до моря, до потоку Кане, і закінчується морем. Ось наділ коліна синів Єфремових, за племенами їх.","І міста відділені синам Єфремовим у наділі синів Манассіїних, усі міста із селами їх.","Але [єфремляни] не вигнали хананеян, які жили в Газері; тому хананеяни жили серед єфремлян до цього дня, платячи їм данину. [Нарешті прийшов фараон, цар Єгипетський, і взяв місто, і спалив його вогнем, і хананеян і ферезеян і жителів Газера перебив, і віддав його фараон у посаг дочці своїй.]"],"x":{"2":"0.28.19","3":"12.6.67-68","4":"0.48.5","5":"3.26.35","9":"5.17.9","10":"5.13.13|6.1.29"}},{"v":["І випав жереб коліну Манассії, оскільки він був первісток Йосифа. Махиру, первісткові Манассії, батькові Галаада, який був хоробрим на війні, припали Галаад і Васан.","Дісталися наділи й іншим синам Манассії, за племенами їх, і синам Авиєзера, і синам Хелека, і синам Асриїла, і синам Шехема, і синам Хефера, і синам Шемиди. Ось діти Манассії, сина Йосифового, чоловічої статі, за племенами їх.","У Салпаада ж, сина Хеферового, сина Галаадового, сина Махирового, сина Манассіїного, не було синів, а [тільки] дочки. Ось імена дочок його: Махла, Ноа, Хогла, Милка і Фирца.","Вони прийшли до священика Єлеазара і до Ісуса, сина Навина, і до начальників, і сказали: Господь повелів Мойсеєві дати нам наділ між братами нашими. І дали їм наділ, за повелінням Господнім, між братами батька їхнього.","І випало Манассії десять ділянок, крім землі Галаадської і Васанської, що за Йорданом;","бо дочки [синів] Манассії одержали наділ серед синів його, а земля Галаадська дісталася іншим синам Манассії.","Межа [синів] Манассії йде від Асира до Михмефафа, що навпроти Сихема; звідси межа йде праворуч до жителів Ен-Таппуаха.","Земля Таппуах дісталася Манассії, а місто Таппуах біля межі Манассіїної — синам Єфремовим.","Звідси межа сходить до потоку Кане, з південного боку потоку. Міста ці належать Єфрему, хоча знаходяться серед міст Манассії. Межа Манассії — на північному боці потоку і закінчується морем.","Те, що на півдні, те Єфремове, а що на півночі, те Манассіїне; море ж було межею їх; до Асира примикали вони з північного боку і до Іссахара зі східного.","В Іссахара й Асира належать Манассії Беф-Сан і залежні від нього місця, Івлеам і залежні від нього місця, жителі Дора і залежні від нього місця, жителі Ен-Дора і залежні від нього місця, жителі Фаанаха і залежні від нього місця, жителі Мегиддона і залежні від нього місця, і третя частина Нафефа [із селами його].","Сини Манассіїні не могли вигнати жителів міст цих, і хананеяни залишилися жити в землі цій.","Коли ж сини Ізраїлеві прийшли в силу, тоді хананеян вони зробили данниками, але вигнати не вигнали їх.","Сини Йосифа говорили Ісусові і сказали: чому ти дав мені в наділ один жереб і одну ділянку, тоді як я багатолюдний, тому що так благословив мене Господь?","Ісус сказав їм: якщо ти багатолюдний, то піди в ліси і там, на землі ферезеїв і рефаїмів, розчисти собі [місце], якщо гора Єфремова для тебе тісна.","Сини Йосифа сказали: не залишиться за нами гора, тому що залізні колісниці у всіх хананеян, які живуть у долині, як у тих, які в Беф-Сані й у залежних від нього місцях, так і в тих, які на долині Ізреельській.","Але Ісус сказав дому Йосифовому, Єфрему і Манассії: ти багатолюдний і сила в тебе велика; не один жереб буде в тебе:","і гора буде твоєю, і ліс цей; ти розчистиш його, і він буде твій до самого кінця його; тому що ти виженеш хананеян, хоча в них колісниці залізні, і хоча вони сильні, [ти подолаєш їх]."],"x":{"1":"0.46.20|3.26.29|3.32.39","2":"3.26.32","3":"3.26.33|3.27.1|3.36.11","4":"3.27.7","9":"5.16.9","11":"6.1.27|8.31.10|11.9.27","12":"5.15.63","13":"4.20.16|5.13.13","14":"3.26.54|0.48.16","16":"6.1.19|38.1.5","18":"5.13.6|58.5.4"}},{"v":["Уся громада синів Ізраїлевих зібралася в Силом, і поставили там скинію зібрання, бо земля була підкорена ними.","Із синів же Ізраїлевих залишалося сім колін, які ще не одержали наділу свого.","І сказав Ісус синам Ізраїлевим: чи довго ви будете байдужими до того, щоб піти і взяти в спадщину землю, яку дав вам Господь Бог батьків ваших?","дайте від себе по три людини з коліна; я пошлю їх, і вони, вставши, пройдуть по землі й опишуть її, як потрібно розділити їм на наділи, і прийдуть до мене;","нехай розділять її на сім наділів; Іуда нехай залишається в межах своїх на півдні, а дім Йосифів нехай залишається в межах своїх на півночі;","а ви розпишіть землю на сім наділів і представте мені сюди: я кину вам жереб тут перед лицем Господа Бога нашого;","а левитам немає частини між вами, тому що священство Господнє є наділом їх; Гад же, Рувим і половина коліна Манассіїного одержали наділ свій за Йорданом на сході, який дав їм Мойсей, раб Господній.","Ці люди встали і пішли. Ісус же тим, що пішли описувати землю, дав такий наказ: підіть, обійдіть землю, опишіть її і поверніться до мене; а я тут кину вам жереб перед лицем Господнім, у Силомі.","Вони пішли, пройшли по землі, [оглянули її] і описали її, за містами її, на сім наділів, у книзі, і прийшли до Ісуса в стан, у Силом.","Ісус кинув їм жереб у Силомі перед Господом, і розділив там Ісус землю синам Ізраїлевим за ділянками їх.","[Перший] жереб вийшов коліну синів Веніамінових, за племенами їх. Межа їх за жеребом ішла між синами Іуди і між синами Йосифа;","межа їх на північному боці починається біля Йордану, і проходить межа ця біля Єрихона з півночі, і піднімається на гору на захід, і закінчується в пустелі Бефавен;","звідти межа йде до Луза, до південного боку Луза, інакше Вефиля, і сходить межа до Атароф-Адара, до гори, що на південному боці Беф-Орона нижнього;","потім межа повертає і сходить до морського боку на південь від гори, що на півдні перед Беф-Ороном, і закінчується біля Кириаф-Ваала, інакше Кириаф-Іарима, міста синів Іудиних. Це західна сторона.","Південною ж стороною від Кириаф-Іарима йде межа до моря і доходить до джерела вод Нефтоаха;","потім межа сходить до кінця гори, що перед долиною сина Енномового, в долині рефаїмів, на півночі, і сходить долиною Еннома до південного боку Ієвуса, і йде до Ен-Рогела;","потім повертає від півночі і йде до Ен-Шемеша, і йде до Гелилофа, що навпроти узвишшя Адуммима, і сходить до каменя Богана, сина Рувимового;","потім проходить біля рівнини на північ і сходить на рівнину;","звідси проходить межа поряд Беф-Хогли на північ, і закінчується межа біля північної затоки моря Солоного, біля південного кінця Йордану. Ось межа південна. Зі східного ж боку межею служить Йордан.","Ось наділ синів Веніамінових, з межами його з усіх боків, за племенами їх.","Міста коліну синів Веніамінових, за племенами їх, належали ці: Єрихон, Беф-Хогла й Емек-Кециц,","Беф-Арава, Цемараїм і Вефиль,","Аввим, Фара й Офра,","Кефар-Аммонай, Афні і Гева: дванадцять міст з їх селами.","Гаваон, Рама і Бероф,","Мицфе, Кефира і Моца,","Рекем, Ірфеїл і Фарала,","Цела, Елеф та Ієвус, інакше Єрусалим, Гивеаф і Кириаф: чотирнадцять міст із їх селами. Ось наділ синів Веніамінових, за племенами їх."],"x":{"1":"5.21.2|10.13.2","7":"36.44.28|3.32.33|4.3.12","9":"9.24.8","11":"4.33.12","12":"5.7.2","13":"0.12.8|5.16.2|10.9.17","14":"5.15.9:60","16":"5.15.7","17":"5.22.10","19":"5.15.2","23":"4.2.23","24":"10.15.22","25":"5.9.17","28":"17.11.4"}},{"v":["Другий жереб припав Симеону, коліну синів Симеонових, за племенами їх; і був наділ їх серед наділів синів Іудиних.","У наділі їх були: Вирсавія або Шева, Молада,","Хацар-Шуал, Вала й Ацем,","Елтолад, Вефул і Хорма,","Циклаг, Беф-Маркавоф і Хацар-Суса,","Беф-Леваоф і Шарухен: тринадцять міст із їх селами.","Аїн, Риммон, Ефер і Ашан: чотири міста із селами їх,","і всі села, що знаходилися навколо міст цих навіть до Ваалаф-Беера, або південної Рами. Ось наділ коліна синів Симеонових, за племенами їх.","Від ділянки синів Іудиних виділено наділ [коліну] синів Симеонових. Оскільки ділянка синів Іудиних була занадто велика для них, то сини Симеонові й одержали наділ серед їхнього наділу.","Третій жереб припав синам Завулоновим за племенами їх, і простягнулася межа наділу їх до Сарида;","межа їх піднімається до моря і Марали і примикає до Дабешефа і примикає до потоку, що перед Іокнеамом;","від Сарида йде назад до східної сторони, на схід сонця, до межі Кислоф-Фавора; звідси йде до Даврафа і піднімається до Іафії;","звідси проходить на схід в Геф-Хефер, у Ітту-Кацин, і йде до Риммона, Мифоара і Неї;","і повертає межа з півночі до Ханнафона і закінчується долиною Іфтах-Ел;","далі: Каттаф, Нагалал, Шимрон, Ідеала і Вифлеєм: дванадцять міст з їх селами.","Ось наділ синів Завулонових, за їхніми племенами; ось міста і села їх.","Четвертий жереб випав Іссахару, синам Іссахара, за племенами їхніми;","межею їх були: Ізреель, Кесуллоф і Сунем,","Хафараїм, Шион і Анахараф,","Раввиф, Кишион і Авец,","Ремеф, Ен-Ганним, Ен-Хадда і Беф-Пацец;","і примикає межа до Фавору і Шагацима і Вефсамиса, і закінчується межа їх біля Йордану: шістнадцять міст із селами їх.","Ось наділ коліна синів Іссахарових за племенами їх; ось міста і села їх.","П’ятий жереб випав коліну синів Асирових, за племенами їх;","межею їх були: Хелкаф, Хали, Ветен і Ахсаф,","Аламелех, Амад і Мишал; і примикає межа до Кармила із західної сторони і до Шихор-Ливнафа;","потім іде назад на схід сонця у Беф-Дагон, і примикає до Завулона і до долини Іфтах-Ел з півночі, [і входить у межі Асафи] у Беф-Емек і Неїел, і йде біля Кавула, з лівого боку;","далі: Еврон, Рехов, Хаммон і Кана, до Сидона великого;","потім межа повертається до Рами до укріпленого міста Тира, і повертає межа до Хосси, і закінчується біля моря, у містечку Ахзиві;","далі: Умма, Афек і Рехов: двадцять два міста з селами їх.","Ось наділ коліна синів Асирових, за племенами їх; ось міста і села їх.","Шостий жереб випав синам Неффалима, синам Неффалима за племенами їх;","межа їх ішла від Хелефа [і] від діброви, що в Цананнимі, до Адами-Некева і Іавнеїла, до Лаккума, і закінчувалася біля Йордану;","звідси повертається межа на захід до Азноф-Фавора і йде звідти до Хуккока, і примикає до Завулона з півдня, і до Асира примикає з заходу, і до Іуди біля Йордану, на схід сонця.","Міста укріплені: Циддим, Цер, Хамаф, Раккаф і Хиннереф,","Адама, Рама й Асор,","Кедес, Едрея й Ен-Гацор,","Іреон, Мигдал-Ел, Хорем, Беф-Анаф і Вефсамис: дев’ятнадцять міст із їх селами.","Ось наділ коліна синів Неффалимових за племенами їх; ось міста і села їх.","Коліну синів Данових, за племенами їх, припав жереб сьомий;","межею наділи їх були: Цора, Ештаол та Ір-Шемеш,","Шаалаввин, Аїалон та Іфла,","Елон, Фимнафа й Екрон,","Елтеке, Гиввефон і Ваалаф,","Ігуд, Бене-Верак і Гаф-Риммон,","Ме-Іаркон і Ракон з межею біля Іоппії. І вийшов наділ синів Данових малим для них.","І сини Данові пішли війною на Ласем і взяли його, й уразили його мечем, і одержали його в спадщину, і оселилися в ньому, і назвали Ласем Даном за ім’ям Дана, батька свого. [Аморреяни залишалися жити в Еломі і Саламині, але рука Єфремова подолала їх, і зробилися вони данниками йому.]","Ось наділ коліна синів Данових, за племенами їх; ось міста і села їх. [Сини Данові не знищили аморреян, які притисли їх на горі, і не давали їм аморреяни виходити на долину і відібрали у них наділ їхньої ділянки.]","Коли закінчили розділення землі, за межами її, тоді сини Ізраїлеві дали серед себе наділ Ісусові, синові Навина:","за повелінням Господнім дали йому місто Фамнаф-Сараі, яке він просив, на горі Єфремовій; і побудував він місто і жив у ньому.","Ось наділи, які Єлеазар священик, Ісус, син Навина, і начальники поколінь розділили колінам синів Ізраїлевих, за жеребом, у Силомі, перед лицем Господнім, при вході в скинію зібрання. І закінчили розподіл землі."],"x":{"1":"4.33.6|0.49.7","2":"12.4.28","3":"12.4.29","4":"4.1.44","8":"12.4.33","10":"50.4.13","11":"6.4.7","13":"11.14.25","15":"6.17.7","18":"8.29.1|9.2.9|10.18.45","26":"10.18.19","27":"10.9.13","28":"0.10.19|5.11.8","33":"50.4.13","34":"4.33.23","35":"3.13.22|10.8.65","40":"6.18.1","41":"5.15.33","43":"10.4.9","44":"10.15.27","46":"42.1.3|54.9.36","47":"4.33.22|6.18.7","49":"3.14.6","50":"5.14.6|5.24.30|6.2.9"}},{"v":["І сказав Господь Ісусові, говорячи:","скажи синам Ізраїлевим: зробіть у себе міста притулку, про які Я говорив вам через Мойсея,","щоб міг тікати туди вбивця, що убив людину помилково, без наміру; нехай [міста ці] будуть у вас притулком [щоб не вмер той, що убив] від того, хто мститься за кров, [доки не постане перед громадою на суд].","І хто втече в одне з міст цих, нехай стане біля воріт міста і розповість уголос старійшинам міста цього справу свою; і вони приймуть його до себе в місто і дадуть йому місце, щоб він жив у них;","і коли поженеться за ним той, хто мститься за кров, то вони не повинні видавати в руки його убивцю, тому що він без наміру убив ближнього свого, не мав до нього ненависти ні вчора, ні третього дня;","нехай він живе в цьому місті, доки не стане перед громадою на суд, доки не помре великий священик, який буде в ті дні. А потім нехай повернеться вбивця і піде в місто своє і в дім свій, у місто, з якого він утік.","І відокремили Кедес у Галилеї на горі Неффалимовій, Сихем на горі Єфремовій, і Кириаф-Арби, інакше Хеврон, на горі Іудиній;","за Йорданом, навпроти Єрихона на схід, відокремили: Бецер у пустелі, на рівнині, від коліна Рувимового, і Рамоф у Галааді від коліна Гадового, і Голан у Васані від коліна Манассіїного;","ці міста призначені для всіх синів Ізраїлевих і для прибульців, які живуть у них, щоб тікав туди всякий, хто убив людину помилково, щоб не помер він від руки того, хто мститься за кров, доки не постане перед громадою [на суд]."],"x":{"2":"3.35.11|4.19.2","3":"3.35.12","6":"3.35.12","7":"4.19.7","8":"4.4.43"}},{"v":["Начальники поколінь левитських прийшли до Єлеазара священика і до Ісуса, сина Навина, і до начальників поколінь синів Ізраїлевих,","і говорили їм у Силомі, в землі Ханаанській, і сказали: Господь повелів через Мойсея дати нам міста для проживання і передмістя їх для худоби нашої.","І дали сини Ізраїлеві левитам з наділів своїх, за повелінням Господнім, ці міста з передмістями їх.","Випав жереб племенам Каафовим; і дісталося за жеребом синам Аарона священика, левитам, від коліна Іудиного, і від коліна Симеонового, і від коліна Веніамінового, тринадцять міст;","а іншим синам Каафа від племен коліна Єфремового, і від коліна Данового, і від половини коліна Манассіїного, за жеребом, дісталося десять міст;","синам Гирсоновим — від племен коліна Іссахарового, і від коліна Асирового, і від коліна Неффалимового, і від половини коліна Манассіїного у Васані, за жеребом, дісталося тринадцять міст;","синам Мерариним, за їх племенами, від коліна Рувимового, від коліна Гадового і від коліна Завулонового — дванадцять міст.","І віддали сини Ізраїлеві левитам ці міста з передмістями їх, як повелів Господь через Мойсея, за жеребом.","Від коліна синів Іудиних, і від коліна синів Симеонових, [і від коліна синів Веніамінових] дали міста, які тут названі поіменно:","синам Аарона, з племен Каафових, із синів Левія [тому що жереб їхній був перший],","дали Кириаф-Арби, батька Єнакового, інакше Хеврон, на горі Іудиній, і передмістя його навколо нього;","а поле цього міста і села його віддали у власність Халеву, синові Ієфонніїному.","Отже, синам Аарона священика дали місто притулку для убивці — Хеврон і передмістя його, Ливну і передмістя її,","Іаттир і передмістя його, Ештемо і передмістя його,","Холон і передмістя його, Давир і передмістя його,","Аїн і передмістя його, Ютту і передмістя її, Беф-Шемеш і передмістя його: дев’ять міст від двох колін цих;","а від коліна Веніамінового: Гаваон і передмістя його, Геву і передмістя її,","Анафоф і передмістя його, Алмон і передмістя його: чотири міста.","Усіх міст синам Аароновим, священикам, дісталося тринадцять міст із передмістями їх.","І племенам синів Каафових, левитів, іншим із синів Каафових, за жеребом їх, дісталися міста від коліна Єфремового;","дали їм місто притулку для вбивці — Сихем і передмістя його, на горі Єфремовій, Гезер і передмістя його,","Кивцаїм і передмістя його, Беф-Орон і передмістя його: чотири міста;","від коліна Данового: Елфеке і передмістя його, Гиввефон і передмістя його,","Аїалон і передмістя його, Гаф-Риммон і передмістя його: чотири міста;","від половини коліна Манассіїного: Фаанах і передмістя його, Гаф-Риммон і передмістя його: два міста.","Усіх міст із передмістями їх іншим племенам синів Каафових дісталося десять.","А синам Гирсоновим, із племен левитських дали: від половини коліна Манассіїного місто притулку для вбивці — Голан у Васані й передмістя його, і Беештеру і передмістя її: два міста;","від коліна Іссахарового: Кишион і передмістя його, Давраф і передмістя його,","Іармуф і передмістя його, Ен-Ганним і передмістя його: чотири міста;","від коліна Асирового: Мишал і передмістя його, Авдон і передмістя його,","Хелкаф і передмістя його, Рехов і передмістя його: чотири міста;","від коліна Неффалимового місто притулку для вбивці — Кедес у Галилеї і передмістя його, Хамоф-Дор і передмістя його, Карфан і передмістя його: три міста.","Усіх міст синам Гирсоновим, за племенами їх, дісталося тринадцять міст із передмістями їх.","Племенам синів Мерариних, решті левитів, дали: від коліна Завулонового Іокнеам і передмістя його, Карфу і передмістя її,","Димну і передмістя її, Нагалал і передмістя його: чотири міста;","[по той бік Йордану навпроти Єрихона] від коліна Рувимового [дано місто притулку для вбивці] Бецер [у пустелі Мисор] і передмістя його, Іааца і передмістя її,","Кедемоф і передмістя його, Мефааф і передмістя його: чотири міста;","від коліна Гадового: міста притулку для вбивці — Рамоф у Галааді й передмістя його, Маханаїм і передмістя його,","Есевон і передмістя його, Іазер і передмістя його: усіх міст чотири.","Усіх міст синам Мерариним за племенами їх, решті племен левитських, за жеребом дісталося дванадцять міст.","Усіх міст левитських серед володінь синів Ізраїлевих було сорок вісім міст із передмістями їх.","При містах цих були при кожнім місті передмістя навколо нього: так було при всіх містах цих. [Коли Ісус скінчив розподіл землі за наділами її, тоді сини Ізраїлеві дали частину Ісусові за повелінням Господнім; дали йому місто, яке він просив, Фимнаф-Сару дали йому на горі Єфремовій, і побудував Ісус місто, яке просив, і жив у ньому. І взяв Ісус кам’яні ножі, якими обрізав синів Ізраїлевих, народжених у путі в пустелі, тому що вони не були обрізані в пустелі; і поклав їх у Фимнаф-Сарі.]","Таким чином віддав Господь Ізраїлю всю землю, яку клявся дати батькам їхнім, і вони одержали її в спадщину й оселилися на ній.","І дав їм Господь спокій з усіх боків, як клявся батькам їх, і ніхто з усіх ворогів їх не встояв проти них; усіх ворогів їхніх віддав Господь до рук їхніх.","Не залишилося невиконаним жодне слово з усіх добрих слів, які Господь говорив дому Ізраїлевому; все збулося."],"x":{"2":"3.35.2","3":"12.6.64","4":"13.31.15","10":"12.6.54","11":"5.14.13|5.15.13","12":"12.6.56","13":"5.10.29","16":"5.15.10|8.6.9","17":"9.2.12|32.28.1","18":"10.2.26|31.10.30|32.1.1","20":"12.6.61","21":"5.20.7","25":"6.1.27","27":"12.6.62|5.20.8","30":"12.6.74","32":"5.20.7","34":"12.6.63","38":"5.20.8","39":"32.49.3","41":"3.35.7","42":"3.35.5","43":"0.12.7|0.13.17","44":"5.22.4","45":"8.3.19|31.34.16|51.7.30"}},{"v":["Тоді Ісус покликав коліно Рувимове, Гадове і половину коліна Манассіїного і сказав їм:","ви виконали все, що повелів вам Мойсей, раб Господній, і слухалися слів моїх в усьому, що я наказував вам;","ви не залишали братів своїх упродовж багатьох днів до цього дня і виконали, що належало виконати за повелінням Господа, Бога вашого:","нині Господь, Бог ваш, заспокоїв братів ваших, як говорив їм; отже, поверніться і підіть у намети ваші, в землю вашого володіння, яку дав вам Мойсей, раб Господній, за Йорданом;","тільки намагайтеся старанно виконувати заповіді і закон, який заповідав вам Мойсей, раб Господній: любити Господа Бога вашого, ходити всіма путями Його, зберігати заповіді Його, приліплятися до Нього і служити Йому всім серцем вашим і всією душею вашою.","Потім Ісус благословив їх і відпустив їх, і вони розійшлися по наметах своїх.","Одній половині коліна Манассіїного дав Мойсей наділ у Васані, а другій половині його дав Ісус наділ з братами його по цей бік Йордану на захід. І коли відпускав їх Ісус у намети їхні і благословив їх,","то сказав їм: з великим багатством повертаєтеся ви в намети ваші, з безліччю худоби, зі сріблом, із золотом, з міддю і з залізом, і з безліччю одягу; розділіть же здобич, узяту у ворогів ваших, із братами своїми.","І повернулися, і пішли сини Рувимові і сини Гадові і половина коліна Манассіїного від синів Ізраїлевих із Силома, що в землі Ханаанській, щоб іти в землю Галаад, у землю свого володіння, яку одержали у володіння за повелінням Господнім, даним через Мойсея.","Прийшовши в околиці Йордану, що в землі Ханаанській, сини Рувимові і сини Гадові і половина коліна Манассіїного спорудили там біля Йордану жертовник, жертовник великий на вигляд.","І почули сини Ізраїлеві, що говорять: ось, сини Рувимові і сини Гадові і половина коліна Манассіїного спорудили жертовник на землі Ханаанській, в околицях Йордану, навпроти синів Ізраїлевих.","Коли почули це сини Ізраїлеві, то зібралася вся громада синів Ізраїлевих біля Силома, щоб іти проти них війною.","Втім, сини Ізраїлеві перше послали до синів Рувимових і до синів Гадових і до половини коліна Манассіїного в землю Галаадську Финеєса, сина Єлеазара, священика,","і з ним десять начальників, по начальнику покоління від усіх колін Ізраїлевих; кожен з них був начальником покоління в тисячах Ізраїлевих.","І прийшли вони до синів Рувимових і до синів Гадових і до половини коліна Манассіїного в землю Галаад і говорили з ними і сказали:","так говорить уся громада Господня: що це за злочин зробили ви перед [Господом] Богом Ізраїлевим, відступивши нині від Господа [Бога Ізраїлевого], спорудивши собі жертовник і повставши нині проти Господа?","Хіба мало для нас беззаконня Фегорового, від якого ми не очистилися до цього дня і за яке вражена була громада Господня?","А ви відступаєте сьогодні від Господа! Сьогодні ви повстаєте проти Господа, а завтра прогнівається [Господь] на всю громаду Ізраїлеву;","якщо ж земля вашого володіння здається вам нечистою, то перейдіть у землю володіння Господнього, в якій знаходиться скинія Господня, візьміть наділ серед нас, але не повставайте проти Господа і проти нас не повставайте, споруджуючи собі жертовник, крім жертовника Господа, Бога нашого;","чи не один Ахан, син Зари, вчинив злочин, узявши з заклятого, а гнів був на всю громаду Ізраїлеву? не один він умер за своє беззаконня.","Сини Рувимові і сини Гадові і половина коліна Манассіїного у відповідь на це говорили начальникам тисяч Ізраїлевих:","Бог богів Господь, Бог богів Господь, Він знає, і Ізраїль нехай знає! Якщо ми повстаємо і відступаємо від Господа, то нехай не пощадить нас Господь у цей день!","Якщо ми спорудили жертовник для того, щоб відступити від Господа [Бога нашого], і для того, щоб приносити на ньому всепалення і приношення хлібне і щоб робити на ньому жертви мирні, то нехай стягне Сам Господь!","Але ми зробили це через побоювання, щоб у майбутні часи не сказали ваші сини нашим синам: «що вам до Господа Бога Ізраїлевого!","Господь поставив межею між нами і вами, сини Рувимові і сини Гадові, Йордан: немає вам частки у Господі». Таким чином ваші сини не допустили б наших синів шанувати Господа.","Тому ми сказали: спорудимо собі жертовник не для всепалення і не для жертв,","але щоб він між нами і вами, між наступними родами нашими, був свідком, що ми можемо служити Господу всепаленнями нашими і жертвами нашими і подяками нашими, і щоб у майбутній час не сказали ваші сини синам нашим: «немає вам частки у Господі».","Ми говорили: якщо скажуть так нам і родам нашим у майбутній час, то ми скажемо: бачите подобу жертовника Господа, яку зробили батьки наші не для всепалення і не для жертви, але щоб це було свідком між нами і вами [і між синами нашими].","Нехай не буде цього, щоб повстати нам проти Господа і відступити нині від Господа, і спорудити жертовник для всепалення і для приношення хлібного і для жертв, крім жертовника Господа Бога нашого, який перед скинією Його.","Финеєс священик, [усі] начальники громади і голови тисяч Ізраїлевих, які були з ним, почувши слова, які говорили сини Рувимові і сини Гадові і сини Манассіїні, схвалили їх.","І сказав Финеєс, син Єлеазара, священик, синам Рувимовим і синам Гадовим і синам Манассіїним: сьогодні ми довідалися, що Господь серед нас, що ви не зробили перед Господом злочину цього; тепер ви визволили синів Ізраїля від руки Господньої.","І повернувся Финеєс, син Єлеазара, священик, і начальники від синів Рувимових і від синів Гадових [і від половини коліна Манассіїного] у землю Ханаанську до синів Ізраїлевих і принесли їм відповідь.","І сини Ізраїлеві схвалили це, і благословили сини Ізраїлеві Бога і не думали більше йти проти них війною, щоб розорити землю, на якій жили сини Рувимові і сини Гадові [і половина коліна Манассіїного].","І назвали сини Рувимові і сини Гадові [і половина коліна Манассіїного] жертовник: Ед*, тому що, сказали вони, він свідок між нами, що Господь є Бог наш."],"x":{"2":"3.32.18|4.3.18","4":"5.13.8|3.32.33","5":"4.8.6|4.10.12","7":"3.32.33|5.13.8","8":"3.31.27|8.30.26","10":"5.18.17","12":"4.13.12","16":"2.17.8-9","17":"3.25.3|4.4.3","19":"5.18.1","20":"5.7.1|12.2.7","22":"4.10.17|25.49.1","27":"0.31.48|5.24.27"},"n":{"34":["Свідок."]}},{"v":["Минуло багато часу після того, як Господь [Бог] заспокоїв Ізраїля від усіх ворогів його з усіх боків, Ісус постарів, увійшов у похилі літа.","І покликав Ісус усіх [синів] Ізраїлевих, старійшин їх, начальників їх, суддів їх і наглядачів їх, і сказав їм: я постарів, увійшов у похилі літа.","Ви бачили все, що зробив Господь Бог ваш перед лицем вашим з усіма цими народами, тому що Господь Бог ваш Сам воював за вас.","Ось, я розділив вам за жеребом народи ці, що залишилися, в наділ колінам вашим, усі народи, які я знищив, від Йордану до великого моря, на захід сонця.","Господь Бог ваш Сам прожене їх від вас [доки не загинуть; і пошле на них диких звірів, доки не знищить їх і царів їхніх від лиця вашого], і знищить їх перед вами, щоб ви одержали у спадщину землю їхню, як говорив вам Господь Бог ваш.","Тому з усією точністю намагайтеся зберігати і виконувати все написане в книзі закону Мойсеєвого, не ухиляючись від нього ні праворуч, ні ліворуч.","Не змішуйтеся з цими народами, які залишилися між вами, не згадуйте імен богів їх, не кляніться [ними] і не служіть їм і не поклоняйтеся їм,","але приліпіться до Господа Бога вашого, як ви робили до цього дня.","Господь прогнав від вас народи великі і сильні, і перед вами ніхто не встояв до цього дня;","один з вас проганяє тисячу, бо Господь Бог ваш Сам воює за вас, як говорив вам.","Тому всіляко намагайтеся любити Господа Бога вашого.","Якщо ж ви відвернетеся і пристанете до залишків з народів цих, які залишилися між вами, і породичаєтеся з ними і будете ходити до них і вони до вас,","то знайте, що Господь Бог ваш уже не буде проганяти від вас народи ці, але вони будуть для вас петлею і сіттю, бичем для ребер ваших і терням для очей ваших, доки не будете знищені з цієї доброї землі, яку дав вам Господь Бог ваш.","Ось, я нині відходжу в путь всієї землі. А ви знаєте всім серцем вашим і всією душею вашою, що не залишилося марним жодне слово з усіх добрих слів, що говорив про вас Господь Бог ваш; усе збулося для вас, жодне слово не залишилося невиконаним.","Але як збулося над вами всяке добре слово, яке говорив вам Господь Бог ваш, так Господь виконає на вас усяке зле слово, доки не знищить вас з цієї доброї землі, яку дав вам Господь Бог ваш.","Якщо ви переступите завіт Господа Бога вашого, який Він уклав з вами, і підете і будете служити іншим богам і поклонятися їм, то запалає на вас гнів Господній, і скоро зникнете з цієї доброї землі, яку дав вам [Господь]."],"x":{"1":"5.21.44|5.22.4","2":"5.24.1","3":"4.9.5","5":"1.14.14|4.6.19","6":"4.5.32","7":"1.23.13|25.15.4|32.5.7","9":"2.26.7","10":"2.26.8|6.3.31","11":"4.4.15","12":"4.7.3|17.10.30","13":"6.2.3|3.33.55|4.7.4","14":"10.2.2|5.21.45|8.3.19","16":"2.26.14|10.9.6-7"}},{"v":["І зібрав Ісус усі коліна Ізраїлеві в Сихем і покликав старійшин Ізраїля і начальників його, і суддів його і наглядачів його, і стали вони перед [Господом] Богом.","І сказав Ісус усьому народові: так говорить Господь Бог Ізраїлів: «за рікою жили батьки ваші здавна, Фарра, батько Авраама і батько Нахора, і служили іншим богам.","Але Я взяв батька вашого Авраама з країни, що по той бік ріки, і водив його по всій землі Ханаанській, і розмножив сім’я його і дав йому Ісаака.","Ісааку дав Якова й Ісава. Ісаву дав Я гору Сеїр у спадщину; Яків же і сини його перейшли в Єгипет [і зробилися там народом великим, сильним і численним, і стали пригноблювати їх єгиптяни].","І послав Я Мойсея й Аарона і покарав Єгипет моровицями, які вчинив Я серед нього, і потім вивів вас.","Я вивів батьків ваших з Єгипту, і ви прийшли до [Червоного] моря. Тоді єгиптяни гналися за батьками вашими з колісницями і вершниками до Червоного моря;","але вони заволали до Господа, і Він поставив [хмару і] темряву між вами та єгиптянами і навів на них море, яке їх і покрило. Очі ваші бачили, що Я зробив у Єгипті. Потім багато часу пробули ви в пустелі.","І привів Я вас до землі аморреян, які жили за Йорданом; вони воювали з вами, але Я віддав їх у руки ваші, і ви одержали в спадщину землю їхню, і Я знищив їх перед вами.","Повстав Валак, син Сепфорів, цар Моавитський, і пішов війною на Ізраїль, і послав і покликав Валаама, сина Веорового, щоб він прокляв вас;","але Я не хотів послухати Валаама, — і він благословив вас, і Я визволив вас з рук його.","Ви перейшли Йордан і прийшли до Єрихона. І стали воювати з вами жителі Єрихона, аморреї, і ферезеї, і хананеї, і хеттеї, і гергесеї, і евеї, і ієвусеї, але Я віддав їх у руки ваші.","Я послав перед вами шершнів, які прогнали їх від вас, двох царів аморрейських; не мечем твоїм і не луком твоїм зроблено це.","І дав Я вам землю, над якою ви не трудилися, і міста, яких ви не будували, і ви живете в них; з виноградних і оливних садів, яких ви не насаджували, ви їсте плоди».","Отже, бійтеся Господа і служіть Йому в чистоті і щирості; відкиньте богів, яким служили батьки ваші за рікою та в Єгипті, а служіть Господу.","Якщо ж не угодно вам служити Господу, то оберіть собі нині, кому служити, чи богам, яким служили батьки ваші, коли були за рікою, або богам аморреян, у землі яких живете; а я і дім мій будемо служити Господу, [тому що Він святий].","І відповів народ і сказав: ні, не буде того, щоб ми залишили Господа і стали служити іншим богам!","Бо Господь — Бог наш, Він вивів нас і батьків наших із землі Єгипетської, з дому рабства, і творив перед очима нашими великі знамення й оберігав нас на всіх путях, якими ми йшли, і серед усіх народів, через які ми проходили.","Господь прогнав від нас усі народи й аморреян, які жили в цій землі. Тому і ми будемо служити Господу, бо Він — Бог наш.","Ісус сказав народу: не зможете служити Господу [Богу], бо Він Бог святий, Бог ревнитель, не потерпить беззаконня вашого і гріхів ваших.","Якщо ви залишите Господа і будете служити чужим богам, то Він наведе на вас зло і знищить вас, після того як благодіяв вам.","І сказав народ Ісусові: ні, ми Господу будемо служити.","Ісус сказав народу: ви свідки за себе, що ви обрали собі Господа — служити Йому? Вони відповіли: свідки.","Отже, відкиньте чужих богів, які у вас, і наверніть серце своє до Господа Бога Ізраїлевого.","Народ сказав Ісусові: Господу Богу нашому будемо служити і голос Його будемо слухати.","І уклав Ісус з народом завіт у той день і дав йому постанови і закон у Сихемі [перед скинією Господа Бога Ізраїлевого].","І вписав Ісус слова ці в книгу закону Божого, і взяв великий камінь і поклав його там під дубом, що біля святилища Господнього.","І сказав Ісус усьому народові: ось камінь цей буде нам свідком, бо він чув усі слова Господа, які Він промовляв нам [сьогодні]; він нехай буде свідком проти вас [у майбутні дні], щоб ви не сказали неправди перед [Господом] Богом вашим.","І відпустив Ісус народ, кожного у свій наділ.","Після цього помер Ісус, син Навина, раб Господній, будучи ста десяти років.","І поховали його в землі його наділу у Фамнаф-Сараі, що на горі Єфремовій, на північ від гори Гааша. [І поклали там з ним у гробі, в якому поховали його, кам’яні ножі, якими Ісус обрізав синів Ізраїлевих у Галгалі, коли вивів їх з Єгипту, як повелів Господь; і вони там навіть до цього дня.]","І служив Ізраїль Господу в усі дні Ісуса і в усі дні старійшин, життя яких продовжилося після Ісуса і які бачили всі діла Господа, які Він сотворив для Ізраїлю.","І кістки Йосифа, які винесли сини Ізраїлеві з Єгипту, поховали в Сихемі, на ділянці поля, яке купив Яків у синів Еммора, батька Сихемового, за сто монет і яке дісталося в наділ синам Йосифовим.","[Після цього] помер і Єлеазар, син Аарона [первосвященик], і поховали його на пагорбі Финеєса, сина його, який дали йому на горі Єфремовій.","[У той день сини Ізраїлеві, взявши ковчег Божий, носили з собою, і Финеєс був священиком замість Єлеазара, батька свого, доки не помер і не був похований у місті своєму Гаваафі.","І сини Ізраїлеві пішли кожен у своє місце й у своє місто.","І стали сини Ізраїлеві служити Астарті й Астарофу і богам навколишніх народів; і віддав їх Господь у руки Еглона, царя Моавитського, і він володів ними вісімнадцять років.]"],"x":{"1":"5.23.2|10.12.1|13.10.1","2":"0.11.26","3":"0.11.31|0.21.2","4":"0.25.26|0.36.8|0.46.6","5":"1.3.10","6":"1.12.37|1.14.9","8":"3.21.25","9":"3.22.5","11":"5.6.1|5.11.3|1.23.23","12":"1.23.28|4.7.20|5.11.20","13":"4.6.10","14":"1.20.2|2.26.1|36.23.3","15":"10.18.21|52.11.23","19":"4.4.24|75.12.29","20":"4.29.25-28|5.23.15-16","23":"0.35.2|8.7.3","24":"32.42.6","25":"4.29.14|11.23.3","26":"6.9.6","27":"0.31.48|5.22.27|31.19.20","28":"6.2.6","29":"4.34.5|6.2.8|0.50.26","30":"5.19.50|6.2.9","32":"0.23.16|0.50.25|54.7.16"}}];
